'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let processAction=false;
let monitoredRun=null;
let budgetPreviewRequest=0;
let datasetProfile='all',datasetLoadRequest=0;
let boot,token,data,questionId,shownRun=null,runList=[],busyId=null,page='workspace',selectedUnit=null,resultTab='answer',lastStatus=null,compareRuns={},comparisonSelection=null;
const artifactCache=new Map(),settingsKey='memory-lab.baseline.settings.v1';
const statusNames={QUEUED:'대기',RUNNING:'실행 중',COMPLETED:'실행 완료',COMPLETED_WITH_ERRORS:'오류 포함 종료',PENDING_REVIEW:'의미 검토 대기',PASS:'사람 판정 통과',FAIL:'검사 실패',ERROR:'실행 오류',CANCELLED:'중단',INTERRUPTED:'서버 종료로 중단',VALIDATION_FAILED:'구조화 검증 실패',BLOCKED:'상위 실패로 미실행',NOT_APPLICABLE:'전체 제공 예산 초과 · 비교 제외'};
const roles={actor:'주체',recipient:'수신자',person:'인물',project:'프로젝트',action:'행동',object:'대상',value:'값',time:'시간',negation:'부정',condition:'조건',intent:'계획',uncertainty:'불확실성',identifier:'식별자'};
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),6500);}
async function api(route,body){const r=await fetch('/api/baseline'+route,{...(body!==undefined?{method:'POST',headers:{'Content-Type':'application/json','X-Memory-Lab-Token':token},body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'로컬 서버 요청 실패');return d;}
function badge(status,label){return `<span class="badge ${esc(status)}">${esc(label||statusNames[status]||status)}</span>`;}
function time(ms){return MemoryTiming.format(ms);}
function errorDetailsHTML(d){
 if(!d)return '<p class="hint">이전 실행에는 세부 원인이 저장되지 않았습니다. 당시 오류 메시지와 기존 판정은 그대로 보존합니다.</p>';
 const names={USER_CANCELLED:'사용자 중단',REQUEST_TIMEOUT:'요청 제한시간 초과',SERVER_NOT_READY:'모델 서버 준비 안 됨',OS_MEMORY_ERROR:'운영체제 메모리 할당 실패',OS_STORAGE_ERROR:'저장 공간 부족',CONNECTION_REFUSED:'연결 거부',CONNECTION_CLOSED:'연결 끊김',CONNECT_TIMEOUT:'서버 연결 시간 초과',HEADERS_TIMEOUT:'응답 시작 대기 시간 초과',BODY_TIMEOUT:'응답 본문 대기 시간 초과',HTTP_ERROR:'모델 서버 HTTP 오류',RESPONSE_JSON_INVALID:'서버 응답 형식 오류',RESPONSE_READ_FAILED:'응답 읽기 실패',TIMEOUT_UNSPECIFIED:'시간 초과 · 종류 미확인',REQUEST_ABORTED:'요청 중단 · 원인 확인 필요',TRANSPORT_UNKNOWN:'통신 실패 · 세부 원인 미확인',EXECUTION_OTHER:'실행 실패 · 상세 확인 필요'};
 const operations={token_count:'본문 토큰 계산',chat_input_count:'전체 입력 토큰 계산',generation:'텍스트 생성',embedding:'임베딩 생성',execution:'실행 처리'},phases={before_request:'요청 전',send_request:'요청 전송·응답 시작 대기',read_response:'응답 본문 읽기',parse_response:'응답 해석'},server=d.server_after||{},mb=n=>Number.isFinite(n)?(n/1048576).toFixed(1)+' MiB':'미기록';
 const entries=[['원인 분류',names[d.category]||d.category],['요청 종류',operations[d.operation]||d.operation||'미기록'],['모델 역할',({generation:'생성 모델',embedding:'임베딩 모델'})[d.role]||'미기록'],['요청 경로',d.endpoint||'미기록'],['실패 구간',phases[d.phase]||d.context?.stage||'미기록'],['요청 경과 시간',Number.isFinite(d.elapsed_ms)?(d.elapsed_ms/1000).toFixed(3)+'초':'미기록'],['하위 오류 코드',d.cause_code||'미기록'],['HTTP 상태',d.http_status??'응답 상태 미확보'],['서버 상태',`${server.status||'미기록'} · PID ${server.pid??'미기록'} · 포트 ${server.port??'미기록'} · 종료 코드 ${server.exit_code??'미확인'}${server.signal_code?' · '+server.signal_code:''}`],['당시 시스템 여유 RAM',mb(d.memory_after?.available_system_ram_bytes)],['당시 웹 서버 메모리',mb(d.memory_after?.web_rss_bytes)],['연결된 질문·원문',[d.context?.question_id,d.context?.source_id,d.context?.summary_part?'요약 구간 '+d.context.summary_part+'/'+d.context.summary_parts:''].filter(Boolean).join(' · ')||'미기록'],['진단 기록 ID',d.event_id]];
 return `<details class="execution-error-details"><summary>실행 오류 상세 · ${esc(names[d.category]||d.category)}</summary>${entries.map(([label,value])=>`<div class="trace-step"><strong>${esc(label)}</strong><small>${esc(value)}</small></div>`).join('')}<p class="hint">메모리 값은 오류 당시의 관측값입니다. 낮은 여유 RAM만으로 오류 원인을 메모리 부족으로 확정하지 않습니다. 자동 재시도는 하지 않습니다.</p>${d.diagnostic_log_saved===false?'<p class="hint">별도 진단 파일 저장은 완료되지 않았습니다. 실행 결과에 포함된 상세를 확인하세요.</p>':''}</details>`;
}
function routeName(route){return route==='R0'?'R0-Chunk':route;}
function isRawRoute(route){return route==='R0'||route==='R0-Full';}
function temporalTags(u){return [['time','시간 표현'],['event_time','사건'],['speech_time','발언'],['valid_from','유효 시작'],['valid_to','유효 종료']].filter(([key])=>u[key]).map(([key,label])=>`<span>${label} ${esc(u[key])}</span>`).join('');}
function currentQuestion(){return data?.questions.questions.find(q=>q.id===questionId);}
function contextFor(q=currentQuestion()){return data?.contexts.contexts.find(c=>c.id===q?.context_id);}
function currentResult(){return shownRun?.results.find(r=>r.question_id===questionId)||(shownRun?.active_result?.question_id===questionId?shownRun.active_result:null);}
function config(){return {dataset:$('#dataset').value,...(!!data?.manifest.profiles?{dataset_profile:datasetProfile,input_path:'raw_original_v1'}:{}),model:$('#local-model').value,method:$('#method').value,structure_version:$('#structure-version').value,route:$('#route').value,top_k:Number($('#top-k').value),seed:Number($('#seed').value),extraction_prompt:$('#extract-prompt').value,answer_prompt:$('#answer-prompt').value,query_prompt:$('#query-prompt').value,extraction_prompt_text:$('#extract-text').value,answer_prompt_text:$('#answer-text').value};}
function saveSettings(){invalidateBudgetPreview();try{localStorage.setItem(settingsKey,JSON.stringify({...config(),questionId}));}catch{}}
function answerPipelineName(mode){
 return ({'scoped-v1':'범위 지정·근거 답변','chronological-v1':'시간순 발췌 답변','question-digest-v1':'질문별 핵심 요약 답변'})[mode]||'기존 방식';
}
function routeRunName(config){
 const name=routeName(config.route);
 return config.route==='M1'?name+' · '+answerPipelineName(config.answer_pipeline):name;
}
function option(v,label){return `<option value="${esc(v)}">${esc(label)}</option>`;}
function datasetLabel(id){return id+({'pma-generalization-v1.0.0':' · 일반화 기준점 · 개발 30 / 확인 30','pma-dev-v0.2.0':' · 랭킹 조건 추가','pma-memory-v3.0.0':' · 누적 기억·장문 · v3','pma-memory-v2.0.0':' · 누적 기억 · 원문 288개','pma-context-v1.0.0':' · 자연 문맥 독립셋','pma-long-v2.0.0':' · 이전 통합본(기존 56개 포함)','pma-long-v1.0.1':' · 장문 통제 56개','pma-dev-v0.1.0':' · 기본 개발셋'}[id]||'');}
function datasetOptions(){return (boot?.datasets||[data.manifest.dataset_version]).map(id=>option(id,datasetLabel(id))).join('');}
function listCount(total,current){return `전체 ${total}개 · 현재 조건 ${current}개`;}
async function showAllQuestions(){datasetProfile='all';$('#family').value='';$('#question-search').value='';initializeDatasetProfile();renderQuestions();saveSettings();}
async function artifact(id){if(!artifactCache.has(id))artifactCache.set(id,api('/artifacts/'+id));return artifactCache.get(id);}
async function hydrate(result){if(!result)return;for(const [key,value]of Object.entries(result.stages)){if(value?.reused&&value.artifact_id&&!value.loaded){const a=await artifact(value.artifact_id);result.stages[key]={...a,artifact_id:value.artifact_id,reused:true,loaded:true};}}}
function setPage(name){page=name;document.body.classList.toggle('is-reviewing',name==='review'||name==='answer-evaluation');document.body.classList.toggle('is-browsing-dataset',name==='datasets');for(const p of ['workspace','history','compare','memory','search','review','datasets','answer-evaluation'])$('#'+p+'-page').hidden=p!==name;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===name));$('#breadcrumb').textContent={workspace:'로컬 Baseline',history:'실제 실행 기록',compare:'나란히 비교',memory:'기억 구조 모아보기',search:'검색 구조 모아보기','answer-evaluation':'인용·의미 판정',review:'기억 검토실',datasets:'데이터셋 둘러보기'}[name];if(name==='datasets')openDatasetBrowser().catch(error=>notify(error.message));if(name==='history')refreshHistory().catch(e=>notify(e.message));if(name==='compare')renderCompareSelectors();if(name==='memory'||name==='search')renderCollection(name).catch(e=>notify(e.message));}
async function loadDataset(id){invalidateBudgetPreview();const request=++datasetLoadRequest;let next;
 try{next=await api('/dataset?id='+encodeURIComponent(id));}catch(error){if(request!==datasetLoadRequest)return false;if(data)$('#dataset').value=data.manifest.dataset_version;throw error;}
 if(request!==datasetLoadRequest)return false;
 data=next;$('#dataset').value=id;datasetProfile=id==='pma-generalization-v1.0.0'?'development':'all';$('#question-search').value='';
 if(shownRun?.config.dataset!==id)shownRun=null;
const families=data.manifest.families;$('#family').innerHTML=option('','전체 계열')+families.map(f=>option(f.id,f.id+' · '+f.title)).join('');if(!data.questions.questions.some(q=>q.id===questionId))questionId=data.questions.questions[0].id;$('#dataset-stats').innerHTML=[['원문',data.sources.records.length+'','원본·수정 스냅샷'],['질문',data.questions.questions.length+'','같은 질문도 상태별 분리'],[['pma-context-v1.0.0','pma-memory-v2.0.0','pma-memory-v3.0.0'].includes(data.manifest.dataset_version)?'의미 주석':data.manifest.dataset_version==='pma-long-v2.0.0'?'판정 주석':data.manifest.counts.target_evidence_regions?'목표 근거 구간':'의미 사실',data.manifest.counts.source_facts+'',data.manifest.dataset_version==='pma-memory-v2.0.0'?'원문별 의미 묶음 · 초안':data.manifest.dataset_version==='pma-context-v1.0.0'?'문장 의미 묶음·대조 · 초안':data.manifest.dataset_version==='pma-long-v2.0.0'?'의미 묶음·대조·기존 구간 · 초안':data.manifest.counts.target_evidence_regions?'전체 사실 주석 아님 · 초안':'작성자 초안 · 검토 필요'],['기억 범위',data.contexts.contexts.length+'','각 실행의 독립된 합성 상태']].map(([l,n,s])=>`<div class="metric"><span>${l}</span><strong>${n}</strong><small>${s}</small></div>`).join('');selectedUnit=null;resetDatasetBrowser();datasetBrowser.id=id;dsIndex(data);if(page==='datasets')renderDatasetBrowser();initializeDatasetProfile();renderQuestions();await selectQuestion(questionId);saveSettings();return true;}
function renderQuestions(){const family=$('#family').value,query=$('#question-search').value.toLocaleLowerCase(),questions=profileQuestions().filter(q=>(!family||q.family_id===family)&&(!query||(q.id+' '+q.text+' '+data.manifest.families.find(f=>f.id===q.family_id)?.title).toLocaleLowerCase().includes(query)));$('#question-count').textContent=listCount(data.questions.questions.length,questions.length);$('#question-list').innerHTML=questions.map(q=>`<button class="q-item ${q.id===questionId?'selected':''}" data-question="${esc(q.id)}"><small>${esc(q.id)} · ${esc(q.question_type)}</small><span>${esc(q.text)}</span>${questionTimingBadge(q.id)}${shownRun?.results.find(r=>r.question_id===q.id)?`<b>${esc(statusNames[shownRun.results.find(r=>r.question_id===q.id).status]||'저장 결과')}</b>`:''}</button>`).join('')||'<div class="empty">검색 결과가 없습니다.</div>';renderStageHelp();}
async function selectQuestion(id){invalidateBudgetPreview();questionId=id;selectedUnit=null;await hydrate(currentResult());renderQuestions();renderWorkspace();saveSettings();}
function highlighted(text,spans=[]){const cuts=new Set([0,text.length]);for(const s of spans){if(s.start<0||s.end>text.length||s.start>=s.end)continue;cuts.add(s.start);cuts.add(s.end);}const points=[...cuts].sort((a,b)=>a-b);let html='';for(let i=0;i<points.length-1;i++){const a=points[i],b=points[i+1],matches=spans.filter(s=>s.start<=a&&s.end>=b).sort((x,y)=>(x.role==='evidence')-(y.role==='evidence')||(x.end-x.start)-(y.end-y.start));const s=matches[0],part=esc(text.slice(a,b));html+=s?`<mark class="${esc(s.role||'evidence')} ${s.active?'active':''}" title="${esc(roles[s.role]||'추출 근거')}">${part}</mark>`:part;}return html;}
function legend(){return '<div class="legend"><span><i></i>인물·역할</span><span><i class="purple"></i>행동·조건</span><span><i class="green"></i>대상·값</span><span><i class="amber"></i>시간</span><span><i class="pink"></i>부정</span><span><i class="teal"></i>계획·불확실성</span></div>';}
function spansFor(result,sourceId){const records=result?.stages.extraction?.records||[];const r=records.find(r=>r.source_id===sourceId);if(!r)return [];const units=selectedUnit? r.units.filter(u=>u.id===selectedUnit.unit_id&&sourceId===selectedUnit.source_id):r.units;return units.flatMap(u=>[...u.evidence.map(e=>({...e,role:'evidence',active:!!selectedUnit})),...u.highlights.map(h=>({...h,active:!!selectedUnit}))]);}
function renderWorkspace(){const q=currentQuestion(),c=contextFor(q),r=currentResult();if(!q)return;
 $('#selected-question').innerHTML=`<div class="meta">${badge('actual',q.id)}<span>${esc(data.manifest.families.find(f=>f.id===q.family_id)?.title)}</span></div><h2>${esc(q.text)}</h2><div class="meta"><span>${esc(c.id)}</span><span>· ${esc(c.actor_id)}</span><span>· 기준 ${esc(c.now)}</span></div>${c.conversation.length?`<details><summary>제공되는 대화·선택 맥락</summary>${c.conversation.map(t=>`<p class="muted">${esc(t.role)} · ${esc(t.text||JSON.stringify(t.items))}</p>`).join('')}</details>`:''}${c.setup.steps.length?`<details><summary>상태 준비 순서 · 합성 fixture</summary><pre>${esc(JSON.stringify(c.setup.steps,null,2))}</pre><p class="hint">실제 제품의 저장 동의·캐시·인증 통합 통과를 뜻하지 않습니다.</p></details>`:''}`;
 const accessible=c.expected_state.accessible_sources,records=accessible.map(x=>data.sources.records.find(s=>s.id===x.source_id));
 $('#sources-panel').innerHTML=`<div class="panel-heading"><h2>기억 범위의 원문</h2><span>${records.length}개 · 원본 보존</span></div>${legend()}${records.map(s=>`<article class="source-card ${selectedUnit?.source_id===s.id?'selected':''}" id="source-${esc(s.id)}"><div class="meta"><strong>${esc(s.id)}</strong><span>v${s.revision} · ${esc(s.metadata.owner_id)}</span></div><div class="source-quote">${highlighted(s.text,spansFor(r,s.id))}</div><small class="muted">${s.metadata.imported_at?'작성':'저장'} 시각 ${esc(s.metadata.created_at||'미제공')}${s.metadata.imported_at?' · 저장 '+esc(s.metadata.imported_at):''}${s.metadata.document_reference_time?' · 문서 기준 '+esc(s.metadata.document_reference_time):''} · ${esc(s.metadata.channel)}</small></article>`).join('')||'<div class="empty">현재 접근 가능한 원문이 없습니다.<br>삭제·비저장·빈 기억 조건을 확인합니다.</div>'}<p class="hint">${r?.stages.extraction?'실제 추출 구절을 역할별로 강조합니다. 카드를 선택하면 연결된 근거만 남습니다.':'실제 추출 전에는 원문 그대로 표시합니다.'}</p>`;
 renderResult(r);renderTrace(q,c,r);renderGold(q);renderDialogueVerdict(shownRun);renderExecutionMonitor(shownRun);
}
function nativeHTML(extraction,mode='workspace',side=''){if(!extraction?.records)return '<div class="empty">이 실행에는 구조화 산출물이 없습니다.<br>R0 원문 경로는 구조화를 건너뜁니다.</div>';return `<div class="meta"><strong>구조화 ${time(extraction.elapsed_ms)}</strong>${extraction.reused?'<span>재사용 · 최초 생성 시간</span>':''}</div>`+extraction.records.map(r=>`<div class="collection"><div class="meta"><strong>${esc(r.source_id)}</strong><span>${r.units.length}개 의미 단위</span>${sourceTimingHTML(r)}</div>${r.units.map(u=>`<button class="native-item ${selectedUnit?.source_id===r.source_id&&selectedUnit?.unit_id===u.id?'selected':''}" ${mode==='compare'?`data-compare-unit="${esc(side+'|'+r.source_id+'|'+u.id)}"`:`data-unit="${esc(r.source_id+'|'+u.id)}"`}><div class="meta"><b>${esc(u.id)}</b><span>${esc(u.evidence.map(e=>e.sentence_id).join(', '))}</span></div><p><strong>${esc(u.subject||'주체 미상')}</strong><span class="arrow">─ ${esc(u.relation||'관계 미상')} →</span>${esc(u.object||'대상 미상')}</p>${u.participants?.length?`<div class="unit-tags">참여자 ${esc(u.participants.join(', '))}</div>`:''}<div class="unit-tags"><span>${esc(u.polarity)}</span><span>${esc(u.status)}</span><span>${esc(u.modality)}</span>${temporalTags(u)}${u.condition?`<span>조건 ${esc(u.condition)}</span>`:''}</div></button>`).join('')||'<p class="notice">추출된 의미 단위가 없습니다. 누락 여부를 검토하세요.</p>'}</div>`).join('');}
function searchHTML(search,answer){if(search?.delivery)return fullSearchHTML(search,answer);if(!search)return '<div class="empty">검색 산출물이 없습니다.</div>';const m=search.metrics;return providedScopeHTML(search,answer)+`<div class="meta">${badge('actual',routeName(search.config.route))}<span>키워드 + 벡터 · RRF</span><span>${time(search.elapsed_ms)}</span></div><p class="muted">실제 검색 입력: ${esc(search.query_used)}</p>${search.warning?`<p class="notice">${esc(search.warning)}</p>`:''}<div class="trace-step">질문 → ${search.index_units.length}개 검색 단위<small>구조화 산출물: ${esc(search.extraction_artifact_id?.slice(0,12)||'사용 안 함')}</small></div><div class="trace-step">원문별 순위 → ${search.selected_sources.length}개 선택<small>근거 ${search.evidence.length}개 · 캐시 재사용 ${search.cache_hits}개 임베딩</small></div>${search.ranked_sources.map(s=>`<div class="rank-item"><div class="rank-head"><b>${s.rank}</b><strong>${esc(s.source_id)}</strong>${search.selected_sources.some(x=>x.source_id===s.source_id)?badge('ready','선택'):''}</div><small>첫 검색 단위 순위 ${s.first_unit_rank}</small>${search.evidence.filter(e=>e.source_id===s.source_id).map(e=>`<p>${esc(e.evidence_id)} → «${esc(e.text)}»</p>`).join('')}</div>`).join('')||'<p class="notice">접근 가능한 검색 결과가 없습니다.</p>'}<p class="hint">정답 근거 그룹 ${m.source_groups_found}/${m.required_groups} · 원문 구간 전체 포함 ${m.span_groups_fully_covered}/${m.required_groups} · MRR ${m.mrr===null?'해당 없음':m.mrr.toFixed(3)}<br>근거의 존재 검사이며 답변 의미 정확도는 아닙니다.</p><details><summary>키워드·벡터별 실제 후보와 점수</summary><pre>${esc(JSON.stringify({lexical:search.lexical_candidates,vector:search.vector_candidates,fused:search.fused_candidates.map(x=>({id:x.id,rank:x.rank,origin:x.origin,fusion_score:x.fusion_score}))},null,2))}</pre></details>`;}
function answerCriteriaHTML(a){
 const snapshot=a.assessment?.criteria_snapshot,g=snapshot?.effective||a.assessment;
 if(!g||!Array.isArray(g.required_claims))return '<aside class="answer-criteria"><h3>판정 기준</h3><p class="notice">이 답변에는 실행 당시 판정 기준이 저장되어 있지 않습니다. 현재 데이터셋의 정답으로 대체하지 않습니다.</p></aside>';
 const list=(rows,empty)=>(rows||[]).map(x=>`<li>${esc(x)}</li>`).join('')||`<li class="muted">${empty}</li>`;
 return `<aside class="answer-criteria" aria-label="답변 판정 기준"><h3>판정 기준</h3><p class="hint">${snapshot?esc(snapshot.version)+' · 분리 판정 기준':'실행 당시 저장된 작성자 초안'} · 모델 입력에 포함하지 않음</p>${snapshot?`<p>${esc(snapshot.note)}</p>${snapshot.needs_revision?'<p class="notice error">기준 확인 필요 · 의미 판정 보류</p>':''}`:''}<h4>예상 답변</h4><p>${g.annotation_status?.reference_answer==='NOT_ANNOTATED'?'대표 답변 미주석':esc(g.reference_answer||'미주석')}</p><h4>기대 행동</h4><p>${esc(g.expected_action||'미주석')}${g.acceptable_actions?.length>1?` · 허용: ${g.acceptable_actions.map(esc).join(' / ')}`:''}</p><h4>필수 의미</h4><ul>${list(g.required_claims,'개별 필수 의미 미주석')}</ul><h4>금지 주장</h4><ul>${list(g.forbidden_claims,'개별 금지 주장 없음 · 근거 없는 주장은 금지')}</ul>${g.structured_expectations?`<details open><summary>구조 기대값</summary>${longStructureHTML(g.structured_expectations)}</details>`:''}<p class="hint">인용 위치 검사는 코드가 확인합니다. 의미·누락·금지 주장은 사람이 확인합니다. 인용 통과가 의미 통과를 뜻하지 않습니다.</p></aside>`;
}
function answerHTML(a){if(!a)return '<div class="empty">답변 산출물이 없습니다.</div>';return `<div class="answer-review-layout"><div class="answer-output">`+tokenUsageHTML(a)+`<div class="meta">${badge(a.assessment.status)}<span>${esc(a.action)} · ${time(a.elapsed_ms)}</span></div><div class="answer">${esc(a.answer)}</div><div>${a.citations.map((c,i)=>`<button class="citation" data-citation="${esc(c.source_id)}">${esc(c.evidence_id)} → ${esc(c.source_id)} · 근거 ${i+1}</button>`).join('')}</div>${a.citations.map(c=>`<p class="muted">«${esc(c.quote)}» · [${c.start}, ${c.end})</p>`).join('')}${a.citation_errors.length?`<div class="notice error">${a.citation_errors.map(esc).join('<br>')}</div>`:''}<p class="hint">인용 구간 ${a.assessment.provenance_valid?'검사 통과':'검사 실패'} · 필수 사실·금지 주장·응답 행동은 사람 판정 필요</p>${a.omitted_by_token_budget.length?`<p class="notice">답변 토큰 예산으로 제외: ${esc(a.omitted_by_token_budget.join(', '))}</p>`:''}`+`</div>${answerCriteriaHTML(a)}</div>`;}
function renderResult(r,refresh=false){if(!r){$('#result-panel').innerHTML=`<div class="empty"><span>↗</span><h3>${shownRun?'이 질문은 선택한 실행에 포함되지 않았습니다.':'첫 실제 결과를 확인하세요'}</h3><p>실행 버튼으로 구조화·검색·답변을 시작하세요.</p></div>`;return;}
 const stage=r.stages,available=[['extraction',stage.extraction?.kind==='summary-only-v1'?'요약 기억':'기억 구조'],['retrieval','검색 구조'],['answer','답변·인용']].filter(([key])=>stage[key]);if(!available.some(([k])=>k===resultTab))resultTab=available.at(-1)?.[0]||'answer';const html=resultTab==='extraction'?nativeHTML(stage.extraction):resultTab==='retrieval'?searchHTML(stage.retrieval,stage.answer):answerHTML(stage.answer);
 const review=shownRun.reviews?.find(v=>v.question_id===r.question_id);
 const live=`<div class="meta"><strong>실제 실행 결과</strong>${badge(r.status)}<span>${esc(shownRun.id)}</span></div>${r.error?`<div class="notice error">${esc(r.error)}</div>${errorDetailsHTML(r.error_details)}`:''}${resultTimingHTML(r)}<div class="tabs">${available.map(([k,label])=>`<button class="tab ${k===resultTab?'active':''}" data-result-tab="${k}">${label}</button>`).join('')}</div>${available.length?html:'<p class="notice">저장된 단계 출력이 없습니다. 오류 메시지를 확인하세요.</p>'}${stage.extraction?.records?`<details><summary>모델의 ${stage.extraction.kind==='summary-only-v1'?'요약':('원래 '+esc(stage.extraction.config.method))} 출력 보기</summary><pre>${esc(JSON.stringify(stage.extraction.records.map(x=>({source_id:x.source_id,native:x.native})),null,2))}</pre></details>`:''}${r.raw_error_output?`<details><summary>오류가 발생한 실제 모델 출력</summary><pre>${esc(r.raw_error_output)}</pre></details>`:''}`;
 const existing=$('#result-live');
 if(refresh&&existing){preservePanelHTML(existing,live);return;}
 $('#result-panel').innerHTML=`<div id="result-live">${live}</div><div class="review-controls"><button class="button primary" data-answer-evaluation="${esc(shownRun.id)}" data-answer-question="${esc(r.question_id)}">인용·의미 분리 판정</button><button class="button primary" data-review-lab="${esc(shownRun.id)}">구조화·검색·답변 검토실 열기</button><p class="hint">아래는 기존 질문 전체 판정입니다. 인용·답변 의미를 따로 확인하려면 분리 판정을 이용하세요.</p><div class="meta"><strong>기존 질문별 종합 판정</strong>${review?badge(review.verdict):badge('PENDING_REVIEW','미검토')}</div><textarea id="review-notes" rows="2" placeholder="필수 사실 누락·잘못된 연결·인용 문제를 기록하세요.">${esc(review?.notes||'')}</textarea><div class="buttons"><button class="button" ${r.status==='NOT_APPLICABLE'?'disabled':''} data-review="PASS">통과</button><button class="button danger" ${r.status==='NOT_APPLICABLE'?'disabled':''} data-review="FAIL">실패</button><button class="button" ${r.status==='NOT_APPLICABLE'?'disabled':''} data-review="PENDING_REVIEW">검토 대기</button><button class="button quiet" data-export-run="${esc(shownRun.id)}">↓ 실행 내보내기</button></div></div>`;
}
function renderTrace(q,c,r){const search=r?.stages.retrieval,ext=r?.stages.extraction,answer=r?.stages.answer;$('#trace-panel').innerHTML=`<h2>실행 경로</h2><div class="trace-step">기억 범위<small>${esc(c.actor_id)} · ${c.expected_state.accessible_sources.length}개 원문</small></div><div class="trace-step">구조화<small>${ext?esc(ext.config.method)+' '+esc(ext.config.structure_version)+' · '+stageTimingHTML(r,'extraction'):stageTimingHTML(r,'extraction')}</small></div><div class="trace-step">검색<small>${search?esc(routeName(search.config.route))+' · '+(search.delivery?'검색 생략 → '+search.evidence.length+'개 전체 원문':search.index_units.length+'개 단위 → '+search.evidence.length+'개 근거')+' · '+stageTimingHTML(r,'retrieval'):stageTimingHTML(r,'retrieval')}</small></div><div class="trace-step">답변<small>${answer?esc(answer.action)+' · 인용 '+answer.citations.length+'개 · '+stageTimingHTML(r,'answer'):stageTimingHTML(r,'answer')}</small></div>${r?.token_budget?`<p class="notice">전체 제공 예산: ${esc(r.token_budget.reasons.join(' · '))}</p>`:''}${r?.corpus_warning?`<p class="trace-note">${esc(r.corpus_warning)}</p>`:''}<details><summary>고정 산출물 ID</summary><pre>${esc(JSON.stringify(Object.fromEntries(Object.entries(r?.stages||{}).map(([k,v])=>[k,v.artifact_id])),null,2))}</pre></details>${r?.unobserved_system_assertions?.length?`<p class="trace-note">별도 통합 관측 필요:<br>${r.unobserved_system_assertions.map(esc).join('<br>')}</p>`:''}<p class="hint">데이터의 정답·하이라이트 주석은 모델 입력에 포함하지 않습니다.</p>`;}
function renderGold(q){if(q.gold.annotation_status?.reference_answer==='NOT_ANNOTATED'){renderLongGold(q);return;}$('#gold-panel').innerHTML=`<h2>판정 기준</h2><p class="hint">작성자 초안 · 모델에 전달하지 않음</p><details open><summary>예상 답변과 필수 사실 보기</summary><p class="muted">기대 행동 · ${esc(q.gold.expected_action)}</p>${q.gold.acceptable_actions?.length>1?`<p class="hint">허용 행동: ${q.gold.acceptable_actions.map(actionLabel).join(' · ')} · 의미와 행동 태그를 분리해 검토합니다.</p>`:''}<p>${esc(q.gold.reference_answer)}</p><h3>필수 의미</h3>${q.gold.required_claims.map(f=>`<p class="muted">· ${esc(f)}</p>`).join('')}<h3>금지 주장</h3>${q.gold.forbidden_claims.map(f=>`<p class="muted">· ${esc(f)}</p>`).join('')||'<p class="muted">개별 금지 주장 없음 · 근거 없는 생성은 항상 금지</p>'}<h3>필요한 근거</h3><pre>${esc(JSON.stringify(q.gold.evidence_groups,null,2))}</pre></details>`;}
function rawChosenIds(){if(!data)return [];const q=currentQuestion(),pool=profileQuestions();return $('#scope').value==='all'?pool.map(q=>q.id):$('#scope').value==='family'?pool.filter(x=>x.family_id===q?.family_id).map(q=>q.id):pool.some(x=>x.id===q?.id)?[q.id]:[];}
function chosenIds(){const ids=rawChosenIds(),out=[],add=id=>{const q=data?.questions.questions.find(q=>q.id===id),c=data?.contexts.contexts.find(c=>c.id===q?.context_id);for(const dep of c?.dialogue?.depends_on||[])if(!out.includes(dep))add(dep);if(!out.includes(id))out.push(id);};ids.forEach(add);return out;}
function renderStageHelp(){if(!data)return;const stage=$('#stage').value,route=$('#route').value,n=chosenIds().length,full=route==='R0-Full';
 $('#top-k').disabled=full;$('#method').disabled=full;$('#structure-version').disabled=full;$('#query-prompt').disabled=full;
 $('#run').disabled=processAction||!!lastStatus?.runtime?.terminating||!!lastStatus?.busy||lastStatus?.setup?.status==='RUNNING'||full&&stage==='extract';$('#stage option[value="extract"]').disabled=full;$('#stage option[value="end_to_end"]').textContent=full?'원문 전체 제공 → 답변':'구조화 → 검색 → 답변';$('#stage option[value="retrieve"]').textContent=full?'원문 제공·예산 확인만':'검색만 · 고정 산출물 사용';
 $('#run').textContent=`▶ ${n}개 질문 ${stage==='extract'?'구조화':stage==='retrieve'?(full?'원문 제공':'검색'):stage==='answer'?'답변':'실행'}`;
 $('#stage-help').textContent=full?(stage==='extract'?'R0-Full에는 구조화가 없습니다. 다른 실행 단계를 선택하세요.':stage==='answer'?'저장된 Full 원문 전체를 재사용하고 현재 답변 프롬프트로 예산을 다시 검사합니다. 일부 근거 제외는 하지 않습니다.':stage==='retrieve'?'접근 가능한 원문 전체 제공과 토큰 예산만 확인합니다. 생성 모델의 토크나이저를 사용하며 임베딩·답변 생성은 하지 않습니다.':'접근 가능한 원문 전체 → 예산 확인 → 답변. 검색·임베딩·Top-K는 사용하지 않습니다. 한도를 넘으면 답변 없이 비교 제외로 기록합니다.'):
 stage==='extract'?'해당 질문의 기억 범위를 구조화합니다. 같은 context는 실행 내에서 한 번만 추출합니다.':stage==='retrieve'?(route==='R0'?'원문 청크를 검색합니다. 생성 모델 호출 없이 임베딩 모델을 사용합니다.':'저장된 추출 결과를 고정해 검색합니다.'):stage==='answer'?'저장된 같은 질문·context 근거를 고정해 답변합니다.':'선택한 경로로 실제 실행합니다. 의미 정확도는 사람 검토가 필요합니다.';
}
function showRuntime(status){lastStatus=status;busyId=status.busy;const runtime=status.runtime,gen=runtime.states.generation,emb=runtime.states.embedding,present=runtime.models.filter(m=>m.present).length,chosen=runtime.models.find(m=>m.id===$('#local-model').value),matching=gen.status==='ready'&&gen.model_id===$('#local-model').value&&($('#route').value==='R0-Full'||emb.status==='ready');$('#runtime-state').className='badge '+(matching?'ready':'');$('#runtime-state').textContent=busyId?'실행 중':status.setup?.status==='RUNNING'?'모델 준비 중':matching?'서버 준비됨':chosen&&!chosen.present?'선택 모델 다운로드 필요':'사용자 실행 대기';$('#runtime-description').textContent=`생성 ${gen.status}${gen.model_id?' ('+gen.model_id+')':''} · 임베딩 ${$('#route').value==='R0-Full'?'미사용 ('+emb.status+')':emb.status} · 모델 파일 ${present}/${runtime.models.length}개 준비`;
 $('#setup-progress').textContent=status.setup?.status==='ERROR'?'설정 오류: '+status.setup.error:status.setup?.status==='RUNNING'?status.setup.progress:gen.error||emb.error||status.setup?.progress||'원문 처리와 모델 평가는 실행 버튼으로만 시작합니다.';
 if(status.runtime.process_check&&!processAction&&!status.runtime.terminating)renderProcessStatus(status.runtime.process_check);$('#terminate-processes').disabled=processAction||!!status.runtime.terminating;$('#refresh-processes').disabled=processAction||!!status.runtime.terminating;const working=processAction||!!status.runtime.terminating||!!busyId||status.setup?.status==='RUNNING';for(const id of ['#download-models','#start-runtime','#stop-runtime','#run'])$(id).disabled=working;$('#run').disabled=working||$('#route').value==='R0-Full'&&$('#stage').value==='extract';$('#cancel').hidden=!busyId;$('#run-progress').hidden=!busyId;updateBudgetPreviewControls();}
async function refreshHistory(){const previous=$('#frozen-run').value;const d=await api('/runs?trash='+($('#trash').checked?'1':'0'));const active=$('#trash').checked?(await api('/runs')).runs:d.runs;runList=active;$('#nav-runs').textContent=active.length;$('#frozen-run').innerHTML=option('','선택하지 않음')+active.map(r=>option(r.id,`${r.id} · ${routeRunName(r.config)} · ${r.stage}`)).join('');if(active.some(r=>r.id===previous))$('#frozen-run').value=previous;
 $('#history-list').innerHTML=d.runs.map(r=>`<article class="history-row card"><div><div class="meta"><h3>${esc(r.id)}</h3>${badge(r.status)}${r.baseline?badge("ready","기준선"):""}</div><p>${esc(r.config.model)} · ${esc(r.config.method)} ${esc(r.config.structure_version)} · ${esc(routeRunName(r.config))} · ${esc(r.stage)}</p><small>${esc(new Date(r.created_at).toLocaleString('ko-KR'))} · ${r.completed}/${r.question_count}개 처리</small>${runTimingHTML(r)}${r.error?`<p>${esc(r.error)}</p>`:''}</div><div class="buttons"><button class="button" data-open-run="${esc(r.id)}">열기</button><button class="button" data-export-run="${esc(r.id)}">↓ 내보내기</button>${["COMPLETED","COMPLETED_WITH_ERRORS"].includes(r.status)?`<button class="button" data-freeze-run="${esc(r.id)}">기준선 지정</button>`:""}<button class="button ${r.deleted_at?'':'danger'}" data-record-action="${r.deleted_at?'restore':'delete'}" data-record-id="${esc(r.id)}">${r.deleted_at?'복원':'삭제'}</button></div></article>`).join('')||'<div class="card empty">아직 저장된 실제 실행이 없습니다.<br>예시 결과와 실제 결과는 별도로 보관합니다.</div>';
}
async function openRun(id,requestedQuestionId){shownRun=await api('/runs/'+id);if(requestedQuestionId&&shownRun.question_ids.includes(requestedQuestionId))questionId=requestedQuestionId;if($('#dataset').value!==shownRun.config.dataset){$('#dataset').value=shownRun.config.dataset;await loadDataset(shownRun.config.dataset);}if(!shownRun.question_ids.includes(questionId))questionId=shownRun.question_ids[0];if(!!data.manifest.profiles){datasetProfile=shownRun.config.dataset_profile||currentQuestion()?.profile||'all';initializeDatasetProfile();}await hydrate(currentResult());resultTab='answer';setPage('workspace');renderQuestions();renderWorkspace();}
async function run(){const frozenId=$('#frozen-run').value;let artifacts=[];if(frozenId){const frozen=await api('/runs/'+frozenId),wanted=$('#stage').value==='answer'?'retrieval':'extraction';artifacts=[...new Set(frozen.results.map(r=>r.stages[wanted]?.artifact_id).filter(Boolean))];}
 const record=await api('/runs',{config:config(),stage:$('#stage').value,question_ids:chosenIds(),artifacts});shownRun={...record,reviews:[]};monitoredRun=shownRun;busyId=record.id;selectedUnit=null;$('#run-progress').hidden=false;$('#run-progress').textContent=record.progress;showRuntime({...lastStatus,busy:record.id});renderWorkspace();notify('사용자 요청으로 실제 로컬 실행을 시작했습니다.');saveSettings();}
async function exportRun(id){const record=await api('/runs/'+id),ids=[...new Set([...record.input_artifacts,...record.results.flatMap(r=>Object.values(r.stages).map(s=>s.artifact_id)).filter(Boolean)])],artifacts={};for(const aid of ids){const a=await artifact(aid);artifacts[aid]=a;if(a.summary_batch_artifact_id&&!ids.includes(a.summary_batch_artifact_id))ids.push(a.summary_batch_artifact_id);if(a.structured_batch_artifact_id&&!ids.includes(a.structured_batch_artifact_id))ids.push(a.structured_batch_artifact_id);for(const r of [...(a.records||[]),...(a.summary_records||[]),...(a.structured_indexes||[]),...(a.indexes||[])])for(const ref of [r.summary_id,r.original_artifact_id,r.index_id])if(ref&&!ids.includes(ref))ids.push(ref);}for(const ref of [record.summary_batch?.artifact_id,record.summary_batch?.structured_batch_artifact_id,record.summary_batch?.indexing?.error_artifact_id])if(ref&&!artifacts[ref]){const pending=[ref];for(const aid of pending){const a=await artifact(aid);artifacts[aid]=a;for(const r of [...(a.records||[]),...(a.indexes||[])])for(const next of [r.summary_id,r.original_artifact_id,r.index_id])if(next&&!artifacts[next]&&!pending.includes(next))pending.push(next);}}const blob=new Blob([JSON.stringify({format:'memory-lab-baseline-export-v1',run:record,artifacts,token_usage:await api('/runs/'+id+'/token-usage'),stage_reviews:await api('/runs/'+id+'/review-export'),answer_reviews:await api('/runs/'+id+'/answer-review-export')},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000);}
function renderCompareSelectors(){for(const side of ['a','b']){const old=$('#compare-'+side).value;$('#compare-'+side).innerHTML=option('','실행 선택')+runList.map(r=>option(r.id,`${r.id} · ${r.config.model} · ${r.config.method} · ${routeRunName(r.config)}`)).join('');if(runList.some(r=>r.id===old))$('#compare-'+side).value=old;}if(!$('#compare-a').value&&runList[0])$('#compare-a').value=runList[0].id;if(!$('#compare-b').value&&runList[1])$('#compare-b').value=runList[1].id;updateComparison().catch(e=>notify(e.message));}
async function updateComparison(){const a=$('#compare-a').value,b=$('#compare-b').value;if(!a||!b){$('#compare-body').innerHTML='<div class="card empty">두 실제 실행을 선택하세요.</div>';return;}compareRuns.a=await api('/runs/'+a);compareRuns.b=await api('/runs/'+b);const A=compareRuns.a,B=compareRuns.b;if(A.dataset_fingerprint!==B.dataset_fingerprint){$('#compare-body').innerHTML='<div class="notice error">데이터 버전 또는 해시가 다른 실행입니다. 같은 입력 비교로 판정하지 않습니다.</div>';$('#compare-question').innerHTML='';return;}
 const common=A.results.filter(r=>B.results.some(s=>s.question_id===r.question_id&&s.context_id===r.context_id)),old=$('#compare-question').value;$('#compare-question').innerHTML=common.map(r=>option(r.question_id,r.question_id+' · '+r.question)).join('');if(common.some(r=>r.question_id===old))$('#compare-question').value=old;await renderComparison();}
async function renderComparison(){const id=$('#compare-question').value;if(!id){$('#compare-body').innerHTML='<div class="card empty">공통으로 실행한 질문이 없습니다.</div>';return;}const A=compareRuns.a,B=compareRuns.b;const diff=Object.keys(A.config).filter(k=>JSON.stringify(A.config[k])!==JSON.stringify(B.config[k]));let html=`<p class="notice">변경된 설정: ${esc(diff.join(', ')||'없음 · 반복 실행 비교')}<br>여러 설정이 다르면 한 요소의 효과로 단정하지 않습니다.</p><div class="compare-grid">`;
 for(const side of ['a','b']){const run=compareRuns[side],r=run.results.find(r=>r.question_id===id);await hydrate(r);const ext=r.stages.extraction,sel=comparisonSelection?.side===side?comparisonSelection:null;html+=`<article class="card"><div class="meta"><strong>${side.toUpperCase()} · ${esc(run.config.method)} ${esc(run.config.structure_version)}</strong>${badge(r.status)}</div><p class="compare-meta">${esc(run.config.model)} · ${esc(routeRunName(run.config))}<br>${esc(run.config.extraction_prompt)} · ${esc(run.config.answer_prompt)}</p><h3>${esc(r.question)}</h3>${r.error?`<p class="notice error">${esc(r.error)}</p>`:''}${ext?.records.map(source=>{const units=sel?source.units.filter(u=>source.source_id===sel.source_id&&u.id===sel.unit_id):source.units;const spans=units.flatMap(u=>[...u.evidence.map(e=>({...e,role:'evidence'})),...u.highlights]);return `<div class="source-card"><div class="meta">${esc(source.source_id)}</div><div class="source-quote">${highlighted(source.text,spans)}</div></div>`;}).join('')||''}${nativeHTML(ext,'compare',side)}${r.stages.retrieval?`<details><summary>실제 검색 경로</summary>${searchHTML(r.stages.retrieval,r.stages.answer)}</details>`:''}${answerHTML(r.stages.answer)}</article>`;}
 $('#compare-body').innerHTML=html+'</div>';}
async function renderCollection(kind){
 const area=$('#'+kind+'-list');area.innerHTML='<div class="card empty">저장된 실제 산출물을 모으는 중…</div>';const seen=new Set(),cards=[];
 for(const summary of runList){const run=await api('/runs/'+summary.id);for(const result of run.results){
  await hydrate(result);const stage=result.stages[kind==='memory'?'extraction':'retrieval'];if(!stage?.artifact_id||seen.has(stage.artifact_id))continue;seen.add(stage.artifact_id);
  const extraction=kind==='memory'?stage:stage.extraction_artifact_id?await artifact(stage.extraction_artifact_id):null;
  const sourceHTML=extraction?extraction.records.map(source=>`<div class="source-card" data-raw-source="${esc(source.source_id)}"><div class="meta">${esc(source.source_id)}</div><div class="source-quote">${highlighted(source.text,source.units.flatMap(u=>[...u.evidence.map(e=>({...e,role:'evidence'})),...u.highlights]))}</div></div>`).join(''):'';
  const extId=kind==='memory'?stage.artifact_id:stage.extraction_artifact_id;
  cards.push(`<article class="card collection" ${extId?`data-extraction-artifact="${esc(extId)}"`:''}><div class="meta"><strong>${esc(run.id)}</strong><span>${esc(result.context_id)}</span><button class="button primary" data-review-lab="${esc(run.id)}" data-review-stage="${kind==='memory'?'extraction':'retrieval'}">단계 검토</button><button class="button" data-open-run="${esc(run.id)}">실행 열기</button></div><p class="compare-meta">${esc(run.config.model)} · ${esc(stage.config.method)} ${esc(stage.config.structure_version)} · ${esc(stage.config.route)}</p>${kind==='memory'?legend()+sourceHTML+nativeHTML(stage,'collection'):searchHTML(stage,result.stages.answer)+(extraction?`<details><summary>검색한 구조와 원문 연결 보기</summary>${legend()}${sourceHTML}${nativeHTML(extraction,'collection')}</details>`:'')}</article>`);
 }}area.innerHTML=cards.join('')||'<div class="card empty">저장된 실제 산출물이 없습니다.</div>';
}
async function selectCollectionUnit(button,sourceId,unitId){const container=button.closest('[data-extraction-artifact]');if(!container)return;const extraction=await artifact(container.dataset.extractionArtifact),same=container.dataset.selectedUnit===sourceId+'|'+unitId;container.dataset.selectedUnit=same?'':sourceId+'|'+unitId;for(const source of extraction.records){const card=[...container.querySelectorAll('[data-raw-source]')].find(c=>c.dataset.rawSource===source.source_id);if(!card)continue;const units=same?source.units:source.source_id===sourceId?source.units.filter(u=>u.id===unitId):[];card.querySelector('.source-quote').innerHTML=highlighted(source.text,units.flatMap(u=>[...u.evidence.map(e=>({...e,role:'evidence',active:!same})),...u.highlights.map(h=>({...h,active:!same}))]));card.classList.toggle('selected',!same&&source.source_id===sourceId);}container.querySelectorAll('[data-unit]').forEach(b=>b.classList.toggle('selected',!same&&b.dataset.unit===sourceId+'|'+unitId));}
// Polling updates only the monitored run and the selected result, never the whole workspace.
function preservePanelHTML(panel,html){
 if(panel.innerHTML===html)return;
 const details=[...panel.querySelectorAll('details')].map(el=>el.open);
 const controls=[...panel.querySelectorAll('input,textarea,select')].map(el=>({key:el.id||el.getAttribute('aria-label')||el.name,value:el.value,checked:el.checked,focused:document.activeElement===el,start:el.selectionStart,end:el.selectionEnd}));
 const scrollTop=panel.scrollTop,scrollLeft=panel.scrollLeft;
 panel.innerHTML=html;
 panel.querySelectorAll('details').forEach((el,i)=>{if(i<details.length)el.open=details[i];});
 panel.querySelectorAll('input,textarea,select').forEach((el,i)=>{const saved=controls[i];if(!saved||saved.key!==(el.id||el.getAttribute('aria-label')||el.name))return;el.value=saved.value;el.checked=saved.checked;if(el.hasAttribute('data-candidate-filter'))filterCandidateChannel(el);if(saved.focused){el.focus({preventScroll:true});if(saved.start!==null&&saved.start!==undefined&&el.setSelectionRange)el.setSelectionRange(saved.start,saved.end);}});
 panel.scrollTop=scrollTop;panel.scrollLeft=scrollLeft;
}
function updateQuestionStatuses(){
 for(const button of document.querySelectorAll('#question-list [data-question]')){
  const r=shownRun?.results.find(r=>r.question_id===button.dataset.question);
  let label=button.querySelector('b');
  if(r){if(!label){label=document.createElement('b');button.append(label);}label.textContent=statusNames[r.status]||'저장 결과';}
 }
}
async function tick(){if(tick.running)return;tick.running=true;try{
 const status=await api('/status');showRuntime(status);
 const id=status.busy||(monitoredRun&&['RUNNING','QUEUED'].includes(monitoredRun.status)?monitoredRun.id:null)||(shownRun&&['RUNNING','QUEUED'].includes(shownRun.status)?shownRun.id:null);
 if(id&&!id.startsWith('SUMMARY-')){
  const viewed=shownRun?.id,qid=questionId,datasetRequest=datasetLoadRequest;
  const before=JSON.stringify(currentResult()),record=await api('/runs/'+id);
  monitoredRun=record;
  $('#run-progress').textContent=record.progress;
  if(status.busy)$('#setup-progress').textContent=record.progress;
  renderExecutionMonitor(record);
  if(viewed===id&&shownRun?.id===id&&datasetRequest===datasetLoadRequest){
   const candidate=record.results.find(r=>r.question_id===qid)||(record.active_result?.question_id===qid?record.active_result:null);
   await hydrate(candidate);
   if(shownRun?.id===id&&datasetRequest===datasetLoadRequest){
    shownRun=record;
    if(page==='workspace'){
     updateQuestionStatuses();
     if(questionId===qid&&before!==JSON.stringify(currentResult())){
      renderResult(currentResult(),true);
      const q=currentQuestion(),c=contextFor(q);if(q&&c)renderTrace(q,c,currentResult());
      for(const ref of c?.expected_state?.accessible_sources||[]){const source=data.sources.records.find(s=>s.id===ref.source_id),quote=$('#source-'+CSS.escape(ref.source_id)+' .source-quote');if(source&&quote)preservePanelHTML(quote,highlighted(source.text,spansFor(currentResult(),source.id)));}
     }
    }
   }
  }
  if(!['RUNNING','QUEUED'].includes(record.status))notify(record.error||'실행이 종료됐습니다. 실제 실행 기록에서 결과를 확인하세요.');
 }else renderExecutionMonitor(monitoredRun||shownRun);
 }catch(e){$('#runtime-description').textContent='로컬 서버 연결 확인 필요: '+e.message;}finally{updateTimingLabels();tick.running=false;}}

document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;try{
 if(b.dataset.page)setPage(b.dataset.page);
 if(b.dataset.question)await selectQuestion(b.dataset.question);
 if(b.dataset.resultTab){resultTab=b.dataset.resultTab;renderResult(currentResult());}
 if(b.dataset.unit){const [source_id,unit_id]=b.dataset.unit.split('|');selectedUnit=selectedUnit?.source_id===source_id&&selectedUnit?.unit_id===unit_id?null:{source_id,unit_id};if(page==='workspace'){renderWorkspace();$('#source-'+CSS.escape(source_id))?.scrollIntoView({behavior:'smooth',block:'nearest'});}else await selectCollectionUnit(b,source_id,unit_id);}
 if(b.dataset.citation){if(page==='workspace')$('#source-'+CSS.escape(b.dataset.citation))?.scrollIntoView({behavior:'smooth',block:'center'});else notify('인용 출처: '+b.dataset.citation);}
 if(b.dataset.openRun)await openRun(b.dataset.openRun,b.dataset.questionId);
 if(b.dataset.exportRun)await exportRun(b.dataset.exportRun);
 if(b.dataset.recordAction){await api('/runs/'+b.dataset.recordId+'/'+b.dataset.recordAction,{});await refreshHistory();notify(b.dataset.recordAction==='delete'?'기록을 삭제했습니다. 삭제 보기에서 복원할 수 있습니다.':'기록을 복원했습니다.');}
 if(b.dataset.freezeRun){await api('/runs/'+b.dataset.freezeRun+'/freeze',{});notify('이 실행의 설정과 산출물을 baseline-v1 기준선으로 지정했습니다.');await refreshHistory();}
 if(b.dataset.review){await api('/runs/'+shownRun.id+'/review',{question_id:questionId,verdict:b.dataset.review,notes:$('#review-notes').value});shownRun=await api('/runs/'+shownRun.id);await hydrate(currentResult());renderResult(currentResult());notify('사람 판정을 저장했습니다.');}
 if(b.dataset.compareUnit){const [side,source_id,unit_id]=b.dataset.compareUnit.split('|');comparisonSelection={side,source_id,unit_id};await renderComparison();}
}catch(e){notify(e.message);}});
async function initialize(){try{
 boot=await api('/bootstrap');token=boot.token;$('#dataset').innerHTML=datasetOptions();$('#local-model').innerHTML=boot.runtime.models.filter(m=>m.role==='generation').map(m=>option(m.id,m.name)).join('');for(const [id,list]of [['extract-prompt',boot.prompts.extraction],['answer-prompt',boot.prompts.answer],['query-prompt',boot.prompts.query]])$('#'+id).innerHTML=list.map(p=>option(p.id,p.name)).join('');$('#extract-text').value=boot.prompts.extraction[0].text;$('#answer-text').value=boot.prompts.answer[0].text;
 let saved;try{saved=JSON.parse(localStorage.getItem(settingsKey));}catch{}if(saved){for(const [key,id]of Object.entries({dataset:'dataset',model:'local-model',method:'method',structure_version:'structure-version',route:'route',top_k:'top-k',seed:'seed',extraction_prompt:'extract-prompt',answer_prompt:'answer-prompt',query_prompt:'query-prompt',extraction_prompt_text:'extract-text',answer_prompt_text:'answer-text'})){if(saved[key]!==undefined&&(!$('#'+id).options||[...$('#'+id).options].some(o=>o.value===String(saved[key]))))$('#'+id).value=saved[key];}questionId=saved.questionId;datasetProfile='all';}
 showRuntime(boot);await loadDataset($('#dataset').value);await refreshHistory();if(boot.busy&&!boot.busy.startsWith('SUMMARY-')){shownRun=await api('/runs/'+boot.busy);await hydrate(currentResult());renderWorkspace();}
 $('#dataset').onchange=()=>loadDataset($('#dataset').value).catch(e=>notify(e.message));$('#show-all-questions').onclick=()=>showAllQuestions().catch(e=>notify(e.message));$('#question-search').oninput=renderQuestions;$('#family').onchange=renderQuestions;$('#scope').onchange=renderStageHelp;$('#stage').onchange=renderStageHelp;
 for(const id of ['local-model','method','structure-version','route','top-k','seed','query-prompt','extract-text','answer-text'])$('#'+id).addEventListener('change',()=>{saveSettings();renderStageHelp();});
 $('#extract-prompt').onchange=()=>{$('#extract-text').value=boot.prompts.extraction.find(p=>p.id===$('#extract-prompt').value).text;saveSettings();};$('#answer-prompt').onchange=()=>{$('#answer-text').value=boot.prompts.answer.find(p=>p.id===$('#answer-prompt').value).text;saveSettings();};
 $('#run').onclick=()=>run().catch(e=>notify(e.message));$('#cancel').onclick=()=>api('/runs/'+busyId+'/cancel',{}).then(()=>notify('중단 요청을 보냈습니다. 진행한 결과는 보존합니다.')).catch(e=>notify(e.message));
 $('#download-models').onclick=()=>api('/models/download',{model_ids:[$('#local-model').value,'qwen3-embedding-06b-q8']}).then(()=>tick()).catch(e=>notify(e.message));$('#start-runtime').onclick=()=>api('/runtime/start',config()).then(()=>tick()).catch(e=>notify(e.message));$('#stop-runtime').onclick=()=>api('/runtime/stop',{}).then(()=>tick()).catch(e=>notify(e.message));
 $('#trash').onchange=()=>refreshHistory().catch(e=>notify(e.message));$('#refresh-history').onclick=()=>refreshHistory().catch(e=>notify(e.message));for(const id of ['compare-a','compare-b'])$('#'+id).onchange=()=>{comparisonSelection=null;updateComparison().catch(e=>notify(e.message));};$('#compare-question').onchange=()=>{comparisonSelection=null;renderComparison().catch(e=>notify(e.message));};setInterval(tick,2000);
 }catch(e){notify(e.message);$('#runtime-description').textContent='초기화 오류: '+e.message;}}
