const selectionCatalog={"revision":"selection-guide-full-request-budget-v2","updated_on":"2026-11-05","groups":[{"key":"dataset","label":"데이터셋","question":"무엇으로 검사하나?","items":[{"id":"pma-dev-v0.1.0","name":"v0.1.0 · 의미·상태 검증","summary":"원문 59개 · 질문 114개 · 기억 범위 55개","detail":"역할·부정·조건·시간·변경·삭제·권한 범위 등 36개 계열의 개발용 초안. 상황별 원문이 최대 4개라 작은 기억 범위의 의미·답변 확인에 적합하다.","change":"첫 개발 데이터셋.","example":"같은 ‘담당자는 누구야?’도 변경 전·후의 기억 범위를 나누어 검사.","limit":"Top-5에 전체 원문이 들어갈 수 있어 검색 재현율만으로 순위 성능을 판단할 수 없다. 최종 미공개 평가셋이 아니다."},{"id":"pma-dev-v0.2.0","name":"v0.2.0 · 랭킹 조건 추가","summary":"원문 93개 · 질문 117개 · 기억 범위 56개","detail":"v0.1.0 내용을 유지하고 F37을 추가했다. F37의 한 기억 범위에 정답 원문 2개와 별도 프로젝트의 유사 원문 32개가 함께 들어 있다.","change":"v0.1.0 대비 +원문 34개, +질문 3개, +기억 범위 1개.","example":"랭킹검증-R의 RAM 변화와 가격을 다른 X 프로젝트 장비 기록 사이에서 검색.","limit":"랭킹 확장은 F37에만 적용된다. 기존 모든 상황에 방해 원문이 추가된 것은 아니다. 정답은 검토 전 초안이며 최종 미공개 평가셋이 아니다."},{"id":"pma-long-v1.0.1","name":"장문 개발셋 v1.0.1","summary":"원문 56개 · 연결 질문 56개 · 6개 프로필","detail":"장문 원본과 질문·정답 초안을 분리하고 사례마다 기억 범위를 격리했다. 역할·부정·조건·정정·동명이인·시간·미상·원거리 연결을 검사한다.","change":"별도 개발셋 추가. 4001자 사례를 4013자에서 수정; 기존 두 데이터셋은 보존.","example":"같은 의미의 짧은 원문과 3000자 앞·중간·끝 변형을 같은 pair_group으로 비교.","limit":"정답은 초안. 목표 근거 60개만 주석. 원문 전체 경로이며 가져오기 경계 분할은 계획만 제공. 토큰수 미측정."},{"id":"pma-long-v2.0.0","name":"이전 통합본 · v2.0.0","summary":"새 이야기 12개 · 새 연결 질문 72개 · 짧은 대조 12개","detail":"업무·일상 각 6개. 한 원문 안 연결 8개와 원문 간 연결 4개에 각 6개 질문을 작성했다. 기존 통제 56개도 보존한다.","change":"기존 통제 56개가 포함된 이전 통합본. 별도 자연 문맥 독립셋을 선택할 수 있습니다.","example":"담당자 인계와 수락을 연결하고, 모바일 알림 완료를 서버 배포 완료와 구분한다.","limit":"작성자 초안. 반복형 통제·자연 문맥·짧은 대조는 별도로 집계한다. 독립 의미 검토·실제 모델 성능·토큰수는 미측정."},{"id":"pma-context-v1.0.0","name":"자연 문맥 독립셋 v1.0.0","summary":"원문 28개 · 질문 84개 · 기존 통제 질문 0개","detail":"자연 문맥 이야기12개(한 원문8·원문 간4)의 질문72개와 그 이야기에서 만든 짧은 대조12개만 담습니다.","change":"기존 자료에 추가하는 통합본과 분리한 별도 선택 항목. 기존 질문은 포함하지 않습니다.","example":"담당 인계·인용 시각·상충 보고를 여러 문장과 원문에서 연결해 확인합니다.","limit":"정답은 작성자 초안. 짧은 대조는 원래 이야기의 변형이며 독립 이야기 수로 합산하지 않습니다. 실제 모델 평가는 미실행."},{"id":"pma-memory-v2.0.0","name":"누적 기억 비교셋 v2.0.0","summary":"원문 288개 · 기본 질문 288개 + 입력 변형 72개","detail":"36개 합성 기억 묶음에 원문 8개씩. 개발 192원문과 최종용 96원문을 분리합니다. 통제 변형은 8개 질문에 원문 2·5·8개와 앞·중간·끝 배치를 적용합니다.","change":"기존 자료 보존, 별도 버전 추가. 개발 A·개발 B·통제·최종 프로필로 나눠 선택합니다.","example":"현재 담당자와 과거 담당자, 중복을 뺀 전체 목록, 실제 지출 합계, 늦게 저장한 옛 기록을 구분합니다.","limit":"정답은 작성자 초안. 모델 실행·실제 토큰 측정은 하지 않았습니다. 실제 삭제·권한·장애는 별도 기능 검사이며 489개 변수 전체를 포함하지 않습니다."},{"id":"pma-memory-v3.0.0","name":"누적 기억·장문 비교셋 v3.0.0","summary":"작성 원문 443개 · 기본 질문 431개 + 변형 240개","detail":"개발·최종 사용자의 기록이 각각 24000자 이상 누적됩니다. 단일 원문 600~24000자, 경계값, 장문 안과 원문 간의 복수 근거, 실제 토큰 단계·상태 변경·생성된 후속 대화를 포함합니다. 현재 v3 안에 서술형 회고·회의 대화·이메일·혼합 입력 8원문과 자연 장문 독해 48질문을 추가했습니다.","change":"새 데이터셋 ID 추가 없이 natural-reading-r1 내용을 추가했습니다. 기존 543원문 항목과 623개 실행 항목은 보존합니다.","example":"상태 변경 전후, 오래된 기록의 늦은 저장, 24000자 원문과 누적 기억을 구분합니다.","limit":"정답은 작성자 초안. 개인 DB·인증·캐시 통합 검사가 아닙니다. 큰 입력은 현재 Full 설정에서 예산 초과로 제외될 수 있습니다."}]},{"key":"method","label":"구조화 방식","question":"어떤 단위로 기억하나?","items":[{"id":"triples","name":"사실·관계","summary":"주체 → 관계·행동 → 대상·값","detail":"독립적인 사실을 facts 배열에 저장한다. 각 사실에 부정·상태·확실성·시간·조건·원문 근거를 붙인다.","change":"의미 사실을 하나씩 비교하기 위한 기준 표현.","example":"민수 → 전달 → PMA 설계 문서 / 수신자 지연은 원문 역할·근거로 함께 보존.","limit":"단순한 세 칸만 저장하는 형식은 아니다. 부정·조건·시간을 함께 보존해야 한다."},{"id":"events","name":"사건 중심","summary":"행위자 + 행동 + 참여자 + 대상","detail":"사건을 events 배열에 저장한다. actor·action·participants·object와 공통 조건·상태·원문 근거를 함께 표현한다.","change":"사실 단위 대신 발생·계획된 사건과 참여자 중심으로 묶는다.","example":"문서 전달 사건: 행위자 민수 · 참여자 지연 · 대상 PMA 설계 문서.","limit":"사건의 묶음 범위는 모델 출력에 달려 있다. 여러 사실을 항상 정확히 하나의 사건으로 합친다는 보장은 없다."},{"id":"entities","name":"개체 중심","summary":"개체별 속성 + 개체 사이 관계","detail":"entities 배열의 개체마다 이름·유형·attributes를 두고, 개체 간 관계는 relationships 배열에 저장한다. 속성과 관계에 원문 근거를 붙인다.","change":"인물·프로젝트 등의 개체를 중심으로 정보를 모은다.","example":"민수 [인물] → 전달 속성 / PMA [프로젝트] 관련 정보와 인물 간 관계.","limit":"전역 개체 통합·동명이인 자동 병합 기능은 아니다. 현재 화면의 카드는 비교를 위해 공통 의미 단위로 펼치며 네이티브 출력은 별도로 보존한다."}]},{"key":"structure-version","label":"방식 버전","question":"같은 표현 안에서 무엇을 강조하나?","items":[{"id":"v1","name":"v1 · 보수적 추출","summary":"명시된 의미와 근거 보존","detail":"추측을 피하고 명시된 의미와 근거를 보존하라는 지침을 적용한다. 시간·조건·부정도 공통 스키마와 기본 지침에 포함된다.","change":"방식별 첫 추출 지침 버전.","example":"‘배포할 계획’은 완료로 바꾸지 않고, 알 수 없는 값은 빈 문자열로 둔다.","limit":"같은 방식의 v2와 JSON 필드는 동일하다. v1이 시간·조건·부정을 추출하지 않는다는 뜻은 아니다."},{"id":"v2","name":"v2 · 역할·시간 강조","summary":"시간·조건·부정·역할 구절 강조","detail":"v1과 동일한 네이티브 스키마를 사용하면서 시간·조건·부정 및 역할 구절을 특히 명시하라는 지침을 적용한다.","change":"출력 필드 변경이 아니라 버전 지침의 강조점 변경.","example":"발언 시각과 사건 시각, 조건 충족과 실제 실행, 주체와 수신자를 더 명시적으로 확인하도록 요청.","limit":"‘추출 프롬프트’ 선택과는 별도 설정이며 두 지침이 함께 적용된다. v2의 성능이 더 좋다고 검증된 것은 아니다."}]},{"key":"route","label":"검색 구성","question":"무엇을 검색 인덱스에 넣나?","items":[{"id":"R0","name":"R0-Chunk · 청크 검색","summary":"원문 청크 → 키워드·임베딩 검색 → 선택 구간 → 답변","detail":"원문 청크를 키워드와 벡터로 검색한다. 전체 경로 실행에서는 구조화를 건너뛴다.","change":"구조화하지 않은 비교 기준선.","example":"‘민수가 지연에게 문서를 전달했다’라는 원문 청크에서 근거를 찾는다.","limit":"구조화 방식·버전은 R0 전체 경로의 검색 입력에 사용되지 않는다. 단, ‘구조화만’ 단계는 검색 구성과 별도로 추출을 실행한다."},{"id":"R0-Full","name":"R0-Full · 원문 전체 제공","summary":"접근 가능한 원문 전체 → 예산 검사 → 답변 · 검색 생략","detail":"현재 질문의 합성 기억 범위·사용자·버전·삭제 조건을 적용한 원문을 주어진 순서대로 전부 제공합니다. 구조화와 임베딩 검색은 생략합니다.","change":"전체 근거가 제공될 때의 답변을 확인하는 별도 기준선입니다.","example":"서로 정정·상충하는 두 원문을 각각 ID와 버전으로 구분해 모두 제공.","limit":"Full은 별도 근거 2048토큰 제한 없이 대화 형식을 포함한 전체 입력 5632토큰을 넘으면 별도 비교 제외 상태입니다. 원문을 자르거나 청크 방식으로 자동 전환하지 않습니다. 검색 순위·Recall·MRR은 해당 없음."},{"id":"S0","name":"S0 · 구조화 검색","summary":"구조화 의미 단위 → 검색 → 원문 근거 → 답변","detail":"실제 추출 결과의 유효한 의미 단위를 키워드와 벡터로 검색하고 연결된 원문 근거를 복원한다.","change":"원문 청크 대신 모델이 보존한 구조화 의미를 검색한다.","example":"주체·행동·대상·부정·조건 등이 직렬화된 의미 단위를 검색한 뒤 해당 원문을 인용.","limit":"추출 누락은 검색에 영향을 준다. ‘검색만’ 단계에서는 같은 기억 범위의 저장된 추출 산출물을 선택해야 한다."},{"id":"H1","name":"H1 · 원문 + 구조화","summary":"원문 청크 + 의미 단위 → 공통 검색 → 원문 근거","detail":"원문 청크와 구조화 의미 단위를 같은 검색 풀에 넣고 키워드·벡터 결과를 결합한다.","change":"두 입력 표현을 함께 사용하는 조합 실험.","example":"구조화에서 놓친 표현을 원문 청크 경로로도 찾을 수 있는지 비교.","limit":"원문 경로가 추출 누락을 보완할 수 있으므로 H1 답변 성공만으로 구조화가 정확했다고 판단하면 안 된다. 별도 재정렬 모델은 사용하지 않는다."}]}],"common":"R0-Chunk·S0·H1은 기존 키워드 + 벡터 검색, 후보 상한 20, 동일 가중 RRF(k=60), 원문별 Top-K를 사용합니다. R0-Full은 검색과 Top-K를 사용하지 않고 기억 범위의 원문 전체를 제공합니다. 전체 문맥 8192·답변 출력 2048·안전 여유 512토큰을 유지하며 Full은 전체 입력 5632토큰, 검색 방식은 별도 근거 2048토큰으로 검사합니다. 의미 정확도는 사람 검토가 필요합니다."};

function renderSelectionGuide(){
 const panel=document.querySelector('#selection-guide');if(!panel)return;
 panel.querySelector('.guide-cards').innerHTML=selectionCatalog.groups.map(group=>{const item=group.items.find(item=>item.id===document.getElementById(group.key).value);return '<article class="guide-card"><small>'+esc(group.label)+' · '+esc(group.question)+'</small><strong>'+esc(item?.name||'선택 대기')+'</strong><p>'+esc(item?.summary||'선택 후 설명을 확인하세요.')+'</p><span>'+esc(item?.change||'')+'</span></article>';}).join('');
 panel.querySelector('.guide-common').textContent=selectionCatalog.common;
 panel.querySelector('.guide-context-note').textContent=document.querySelector('#stage').value==='answer'?'답변만 실행하면 선택한 저장 검색 산출물을 사용합니다. 현재 검색 구성 선택이 그 산출물을 다시 검색하거나 변경하지 않습니다.':document.querySelector('#stage').value==='retrieve'&&!['R0','R0-Full'].includes(document.querySelector('#route').value)?'검색만 실행하면 선택한 저장 추출 산출물을 사용합니다. 현재 구조화 방식·버전으로 다시 추출하지 않습니다.':'';
}
function initializeSelectionGuide(){
 const panel=document.querySelector('#selection-guide');if(!panel)return;
 panel.querySelector('.guide-reference').innerHTML=selectionCatalog.groups.map(group=>'<div class="guide-group"><h3>'+esc(group.label)+' <small>'+esc(group.question)+'</small></h3>'+group.items.map(item=>'<article class="guide-reference-item"><strong>'+esc(item.name)+'</strong><p>'+esc(item.detail)+'</p><p class="guide-change">차이: '+esc(item.change)+'</p><p>예: '+esc(item.example)+'</p><p class="guide-limit">확인: '+esc(item.limit)+'</p></article>').join('')+'</div>').join('');
 for(const id of ['dataset','method','structure-version','route','stage','frozen-run'])document.getElementById(id).addEventListener('change',renderSelectionGuide);
 renderSelectionGuide();
}
initializeSelectionGuide();
