// Saved-run evidence viewer. Reads frozen snapshots only; never starts a model.
const historyEvidence={request:0,run:null,panel:null,opener:null,questionId:null,tab:'extraction',unit:null,item:null,extraction:null};
function heResult(){const h=historyEvidence;return h.run?.results?.find(r=>r.question_id===h.questionId)||(h.run?.active_result?.question_id===h.questionId?h.run.active_result:null);}
function heUnits(){return (historyEvidence.extraction?.records||[]).flatMap(record=>(record.units||[]).map(unit=>({record,unit})));}
function heSources(result){
 const sources=[],add=s=>{if(typeof s.text!=='string')return;const base=Number.isInteger(s.base)?s.base:0;if(sources.some(x=>x.id===s.id&&x.revision===s.revision&&x.base===base))return;sources.push({...s,base});};
 for(const record of historyEvidence.extraction?.records||[])add({id:record.source_id,revision:record.revision,text:record.text??record.source_snapshot?.text});
 for(const source of result?.stages?.retrieval?.source_snapshots||[])add({id:source.id,revision:source.revision,text:source.text});
 for(const e of [...(result?.stages?.retrieval?.evidence||[]),...(result?.stages?.answer?.evidence_used||[])]){
  if(sources.some(s=>s.id===e.source_id&&s.revision===e.revision&&!s.partial))continue;
  if(Number.isInteger(e.start))add({id:e.source_id,revision:e.revision,text:e.text,base:e.start,partial:true});
 }
 return sources;
}
function heSpan(source,span,role='evidence'){
 if(span.source_id!==undefined&&span.source_id!==source.id||span.revision!==undefined&&span.revision!==source.revision)return null;
 const start=span.start-source.base,end=span.end-source.base,quote=span.quote??span.text;
 if(!Number.isInteger(start)||!Number.isInteger(end)||start<0||end<=start||end>source.text.length||typeof quote!=='string'||source.text.slice(start,end)!==quote)return null;
 return {start,end,quote,role:Object.hasOwn(roles,role)?role:'evidence',active:true};
}
function heItems(result){return historyEvidence.tab==='retrieval'?result?.stages?.retrieval?.evidence||[]:result?.stages?.answer?.citations||[];}
function heSourceSpans(source,result){
 const h=historyEvidence,units=heUnits(),chosen=h.unit===null?null:units[h.unit],items=heItems(result),item=h.item===null?null:items[h.item];
 const matching=units.filter(x=>x.record.source_id===source.id&&x.record.revision===source.revision&&(!chosen||x===chosen));
 if(h.tab==='extraction')return matching.flatMap(({unit})=>[...(unit.evidence||[]).map(e=>heSpan(source,e)),...(unit.highlights||[]).map(e=>heSpan(source,e,e.role))]).filter(Boolean);
 const evidence=(item?[item]:items).map(e=>heSpan(source,e)).filter(Boolean);
 const roleSpans=matching.flatMap(({unit})=>(unit.highlights||[]).map(e=>heSpan(source,e,e.role))).filter(s=>s&&evidence.some(e=>s.start>=e.start&&s.end<=e.end));
 return [...evidence,...roleSpans];
}
function heEvidenceHTML(result){
 const h=historyEvidence,units=heUnits();
 if(h.tab==='extraction')return units.map(({record,unit},i)=>`<button class="he-link ${h.unit===i?'selected':''}" data-he-unit="${i}" aria-pressed="${h.unit===i}"><small>${esc(record.source_id)} · v${esc(record.revision)} · ${esc(unit.id)}</small><strong>${esc(unit.subject||'주체 미상')} <span>→ ${esc(unit.relation||'관계 미상')} →</span> ${esc(unit.object||'대상 미상')}</strong><span class="unit-tags">${[unit.time,unit.condition,unit.status,unit.modality].filter(Boolean).map(x=>`<span>${esc(x)}</span>`).join('')}</span>${(unit.evidence||[]).map(e=>`<q>${esc(e.quote)}</q>`).join('')}${unit.validation_errors?.length?'<span class="notice">원문 위치·형식 오류가 있는 추출입니다. 일치하는 구간만 강조합니다.</span>':''}</button>`).join('')||'<p class="notice">저장된 구조화가 없습니다. 원문 검색(R0)이나 추출 전 오류일 수 있습니다.</p>';
 const items=heItems(result),answer=result?.stages?.answer,search=result?.stages?.retrieval;
 return (h.tab==='answer'?`<h3>실제 답변</h3><div class="he-answer">${esc(answer?.answer||'저장된 답변이 없습니다.')}</div><h3>답변 인용 → 원문</h3>`:`<p class="muted">검색 입력: ${esc(search?.query_used||'검색 기록 없음')}</p><p class="muted">키워드 후보 ${search?.lexical_candidates?.length??0}개 · 의미 후보 ${search?.vector_candidates?.length??0}개 · 선택 원문 ${search?.selected_sources?.length??0}개</p><h3>검색 근거 → 원문</h3>`)+items.map((e,i)=>`<button class="he-link ${h.item===i?'selected':''}" data-he-item="${i}" aria-pressed="${h.item===i}"><small>${esc(e.evidence_id)} → ${esc(e.source_id)} · v${esc(e.revision)}</small><q>${esc(e.quote??e.text)}</q><small>원문 위치 [${esc(e.start)}, ${esc(e.end)})</small></button>`).join('')+(items.length?'':'<p class="notice">이 단계에 저장된 근거 구간이 없습니다.</p>');
}
function renderHistoryEvidence(){
 const h=historyEvidence,panel=h.panel;if(!h.run||!panel?.isConnected)return;const result=heResult(),sources=heSources(result),units=heUnits(),items=heItems(result),chosen=h.unit===null?null:units[h.unit],item=h.item===null?null:items[h.item];
 panel.innerHTML=`<div class="section-heading"><div><h3>저장된 원문 하이라이트</h3><p>${esc(h.run.id)} · 당시 원문과 실제 산출물</p></div><div class="buttons"><button class="button" data-he-refresh>새로고침</button><button class="button" data-he-close>닫기</button></div></div><label class="he-question-label">질문<select data-he-question>${(h.run.question_ids||[]).map(id=>option(id,id+' · '+(h.run.results.find(r=>r.question_id===id)?.question||(h.run.active_result?.question_id===id?h.run.active_result.question:'미실행')))).join('')}</select></label><div class="tabs">${[['extraction','기억 구조'],['retrieval','검색 근거'],['answer','답변 인용']].map(([key,label])=>`<button class="tab ${h.tab===key?'active':''}" data-he-tab="${key}" aria-pressed="${h.tab===key}">${label}</button>`).join('')}</div>${result?.error?`<p class="notice error">${esc(result.error)}</p>`:''}${!result?'<p class="notice">이 질문은 아직 실행되지 않았습니다.</p>':''}${h.extraction&&h.extraction!==result?.stages?.extraction?'<p class="hint">저장된 검색 산출물에 연결된 구조화입니다. 이 실행에서 새로 추출한 결과와 구분합니다.</p>':''}${legend()}<p class="hint">근거·관계 카드를 누르면 연결된 구간을 강조합니다. 색상은 저장된 추출 역할이며, 의미 정확도 판정은 별도입니다.</p><div class="he-layout"><div class="he-sources">${sources.map((source,i)=>{const spans=heSourceSpans(source,result),focused=chosen?chosen.record.source_id===source.id&&chosen.record.revision===source.revision:item?!!heSpan(source,item):false;return `<article class="source-card ${focused?'selected':''}" data-he-source="${i}"><div class="meta"><strong>${esc(source.id)}</strong><span>v${esc(source.revision)}${source.partial?' · 저장된 근거 구간':' · 원문 스냅샷'}</span></div><div class="source-quote">${highlighted(source.text,spans)}</div>${source.partial?`<small>원문 전체가 없는 기록입니다. 저장된 구간 [${source.base}, ${source.base+source.text.length})만 표시합니다.</small>`:''}</article>`;}).join('')||'<p class="notice">이 기록에 원문 스냅샷이 없습니다. 현재 데이터셋의 원문으로 대체하지 않습니다.</p>'}</div><div class="he-relations">${heEvidenceHTML(result)}</div></div><p class="hint">정답 주석을 실제 추출 하이라이트에 섞지 않습니다. 원문과 위치가 일치하지 않는 구간은 강조하지 않습니다.</p>`;
 const select=panel.querySelector('[data-he-question]');select.value=h.questionId;select.onchange=()=>{h.questionId=select.value;h.unit=null;h.item=null;loadHistoryEvidenceQuestion().catch(e=>notify(e.message));};
}
async function loadHistoryEvidenceQuestion(){
 const h=historyEvidence,request=++h.request,result=heResult();if(!h.panel)return;h.panel.inert=true;
 try{if(result?.stages)await hydrate(result);let ext=result?.stages?.extraction;if(!ext&&result?.stages?.retrieval?.extraction_artifact_id)ext=await artifact(result.stages.retrieval.extraction_artifact_id);if(request!==h.request)return;h.extraction=ext||null;renderHistoryEvidence();}
 catch(e){if(request===h.request&&h.panel?.isConnected)h.panel.innerHTML=`<p class="notice error">저장된 산출물 조회 실패: ${esc(e.message)}</p><button class="button" data-he-refresh>다시 불러오기</button><button class="button" data-he-close>닫기</button>`;}
 finally{if(request===h.request&&h.panel)h.panel.inert=false;}
}
function closeHistoryEvidence(){const h=historyEvidence;++h.request;if(h.panel){h.panel.hidden=true;h.panel.inert=false;}h.opener?.setAttribute('aria-expanded','false');h.run=null;h.panel=null;h.opener=null;h.extraction=null;}
async function openHistoryEvidence(opener,refresh=false){
 const h=historyEvidence,panel=opener.closest('.history-row')?.querySelector('.history-evidence-panel');if(!panel)return;
 if(!refresh&&h.panel===panel&&!panel.hidden){closeHistoryEvidence();return;}
 const wanted=refresh?h.questionId:null;closeHistoryEvidence();h.panel=panel;h.opener=opener;panel.hidden=false;opener.setAttribute('aria-expanded','true');panel.innerHTML='<p class="muted">저장된 원문과 실제 산출물을 불러오는 중…</p>';
 const request=++h.request;
 try{const run=await api('/runs/'+encodeURIComponent(opener.dataset.historyEvidence));if(request!==h.request)return;h.run=run;h.questionId=run.question_ids.includes(wanted)?wanted:run.question_ids[0];h.unit=null;h.item=null;h.tab=run.stage==='answer'?'answer':isRawRoute(run.config.route)?'retrieval':'extraction';await loadHistoryEvidenceQuestion();}
 catch(e){if(request===h.request){panel.innerHTML=`<p class="notice error">${esc(e.message)}</p><button class="button" data-he-close>닫기</button>`;}}
}
document.addEventListener('click',async event=>{
 const b=event.target.closest('[data-history-evidence],[data-he-close],[data-he-refresh],[data-he-tab],[data-he-unit],[data-he-item]');if(!b)return;const h=historyEvidence;
 try{
  if(b.dataset.historyEvidence)await openHistoryEvidence(b);
  else if(b.hasAttribute('data-he-close'))closeHistoryEvidence();
  else if(b.hasAttribute('data-he-refresh')){if(h.opener)await openHistoryEvidence(h.opener,true);}
  else if(b.dataset.heTab){h.tab=b.dataset.heTab;h.unit=null;h.item=null;renderHistoryEvidence();}
  else{if(b.dataset.heUnit!==undefined){const i=Number(b.dataset.heUnit);h.unit=h.unit===i?null:i;}else{const i=Number(b.dataset.heItem);h.item=h.item===i?null:i;}renderHistoryEvidence();h.panel?.querySelector('.source-card.selected')?.scrollIntoView({behavior:'smooth',block:'nearest'});}
 }catch(e){notify(e.message);}
});

// Original delivery views use saved source snapshots and actual evidence only.
function fullBudgetHTML(budget){
 const modern=budget.budget_policy==='full-request-only-v2',input=budget.input_tokens??budget.input_tokens_estimate;
 return `<div class="raw-token-summary"><strong>${modern?'전체 요청 기준 · v2':'이 실행 당시의 이전 예산 정책'}</strong><span>${modern?'대화 형식 포함 전체 입력':'전체 입력 사전 추정'} ${input}/${budget.input_limit}토큰</span><span>출력 예약 ${budget.output_limit} · 안전 여유 ${budget.template_margin} · 전체 문맥 ${budget.context_limit??8192}</span><span>입력 잔여 ${budget.input_limit-input}토큰${input>budget.input_limit?' · 전체 입력 한도 초과':''}</span><small>원문·메타데이터 ${budget.evidence_tokens}토큰${modern?' · 별도 근거 제한 없음':` / 당시 근거 제한 ${budget.evidence_limit}토큰`}<br>${modern?'토큰 계산은 답변 생성 없이 실제 요청 형식으로 수행합니다.':'이전 실행의 측정값과 판정은 그대로 보존합니다.'}</small></div>`;
}
function tokenUsageHTML(answer){
 if(!answer)return '';const usage=answer.response?.usage,budget=answer.token_budget;
 return `<div class="raw-token-summary"><strong>실제 토큰 사용</strong><span>입력 ${usage?.prompt_tokens??'미측정'} · 출력 ${usage?.completion_tokens??'미측정'}</span></div>${budget?fullBudgetHTML(budget):''}`;
}
function invalidateBudgetPreview(){budgetPreviewRequest++;const panel=$('#budget-preview-result');if(panel)panel.innerHTML='<p class="hint">선택한 질문·설정으로 다시 계산해 주세요. 표시 범위는 선택 질문 하나입니다.</p>';updateBudgetPreviewControls();}
function updateBudgetPreviewControls(){const button=$('#preview-budget');if(!button)return;button.disabled=!!busyId||processAction||lastStatus?.setup?.status==='RUNNING'||$('#route').value!=='R0-Full';}
async function previewSelectedBudget(){
 const request=++budgetPreviewRequest,qid=questionId,settings=JSON.stringify(config()),panel=$('#budget-preview-result');
 panel.innerHTML='<p class="hint">선택 질문의 실제 요청 토큰을 계산 중입니다. 답변은 생성하지 않습니다.</p>';
 try{const result=await api('/budget-preview',{config:JSON.parse(settings),question_id:qid});if(request!==budgetPreviewRequest||qid!==questionId||settings!==JSON.stringify(config()))return;
 panel.innerHTML=`<p><strong>${esc(qid)} · ${result.scope==='SEED_ONLY'?'앞 턴 미포함 · 확정 전':result.budget.eligible?'전체 제공 가능':'전체 입력 한도 초과 · 비교 제외'}</strong></p>${fullBudgetHTML(result.budget)}<p class="hint">${esc(result.note)} · 원문 ${result.sources}개 · 배치 전체 판정이 아닙니다.</p>`;
 }catch(error){if(request===budgetPreviewRequest)panel.innerHTML=`<p class="notice">${esc(error.message)}</p>`;}
}
document.addEventListener('click',event=>{if(event.target.closest('button')?.id==='preview-budget')previewSelectedBudget();});
document.addEventListener('input',event=>{if(event.target.closest('#extract-text,#answer-text,#top-k,#seed'))invalidateBudgetPreview();});
document.addEventListener('change',event=>{if(event.target.closest('#dataset,#local-model,#route,#method,#structure-version,#extract-prompt,#answer-prompt,#query-prompt,#scope,#stage,#frozen-run'))invalidateBudgetPreview();});

function providedScopeHTML(search,answer){
 if(!search)return '';const snapshots=search.source_snapshots||[],used=answer?.evidence_used||search.evidence||[];
 return `<details class="raw-provided-scope"><summary>${answer?'답변에 실제 제공한':'답변 제공 준비'} 원문 범위 · ${new Set(used.map(e=>e.source_id)).size}/${snapshots.length}개 원문</summary>${search.delivery?.status==='BUDGET_EXCEEDED'?'<p class="notice">전체 제공 예산을 넘었습니다. 아래 원문은 후보이며 답변 모델에는 보내지 않았습니다.</p>':''}${snapshots.map(source=>{const spans=used.filter(e=>e.source_id===source.id&&e.revision===source.revision).map(e=>({start:e.start,end:e.end,role:'evidence'})).sort((a,b)=>a.start-b.start);let end=0,covered=0;for(const span of spans){covered+=Math.max(0,span.end-Math.max(end,span.start));end=Math.max(end,span.end);}return `<article class="source-card"><div class="meta"><strong>${esc(source.id)}</strong><span>v${source.revision} · 포함 ${covered}/${source.text.length}자</span></div><div class="source-quote">${highlighted(source.text,spans)}</div></article>`;}).join('')||'<p class="notice">접근 가능한 원문이 없습니다.</p>'}<p class="hint">하이라이트는 저장된 전달 구간입니다. 원문에 근거가 있다는 사실과 답변의 의미 정확도는 별도로 검토합니다.</p></details>`;
}
function fullSearchHTML(search,answer){
 const delivery=search.delivery,budget=delivery.budget;
 return `<div class="meta">${badge('actual','R0-Full')}<span>검색·임베딩 생략</span><span>${time(search.elapsed_ms)}</span></div><p class="notice">${esc(search.warning)}</p><p><strong>${budget.eligible?'원문 전체 제공 가능':'전체 제공 예산 초과 · 비교 제외'}</strong></p>${fullBudgetHTML(budget)}<p class="hint">기억 범위 원문 ${delivery.candidate_sources}개 · 총 ${delivery.candidate_characters}자 · 원문 순서 고정 · 일부 제외 및 자동 전환 없음</p>${providedScopeHTML(search,answer)}<p class="hint">검색 Recall·MRR·검색 순위: 해당 없음. 생성 모델의 토크나이저로 예산을 확인하며, 검색 점수를 만들지 않습니다.</p>`;
}
function resourceSummaryHTML(run){
 const resource=run?.resources;if(!resource)return '<p class="hint">이 실행의 자원 측정 기록이 없습니다.</p>';
 const gib=n=>(n/1024**3).toFixed(2),mib=n=>Math.round(n/1024**2);
 return `<p class="hint">시스템 여유 RAM 최저 ${gib(resource.min_available_ram_bytes)}GB · 웹 서버 RAM 최고 ${mib(resource.peak_web_rss_bytes)}MB<br>진행 이벤트 ${resource.samples}회 표본입니다. 시스템 수치는 다른 프로그램의 영향을 포함하며, 모델별 RAM·GPU 최고값은 미측정입니다.</p>`;
}
const rawOriginalComparison=renderComparison;
renderComparison=async function(){
 await rawOriginalComparison();const a=compareRuns.a,b=compareRuns.b;if(!a||!b||a.dataset_fingerprint!==b.dataset_fingerprint||!$('#compare-question').value)return;
 const common=a.results.filter(r=>b.results.some(s=>s.question_id===r.question_id&&s.context_id===r.context_id));
 const excluded=common.filter(r=>r.status==='NOT_APPLICABLE'||b.results.find(s=>s.question_id===r.question_id).status==='NOT_APPLICABLE');
 $('#compare-body').insertAdjacentHTML('afterbegin',`<div class="raw-compare-summary"><strong>같은 질문 ${common.length}개 · 공통 적용 가능 ${common.length-excluded.length}개 · 전체 제공 예산 제외 ${excluded.length}개</strong><p>실행 오류는 성공으로 간주하지 않습니다. 예산 제외는 답변 성능 실패와 구분하며 양쪽 공통 조건에서 비교하세요.</p>${[a,b].map((run,i)=>`<div><b>${i?'B':'A'} · ${esc(routeRunName(run.config))}</b>${resourceSummaryHTML(run)}</div>`).join('')}</div>`);
};


// MEMORY CORPUS V2: inspecting data never starts models or creates runs.
function renderMemoryCorpusInfo(){
 const panel=$('#long-dataset-info'),m=data.manifest,q=currentQuestion(),c=contextFor(q),refs=c?.expected_state.accessible_sources||[];
 const selected=data.coverage.profiles.find(p=>p.id===datasetProfile),counts={PARTIAL:0,NOT_COVERED:0,SEPARATE_FUNCTIONAL_TEST:0};
 for(const v of data.coverage.variables)counts[v.status]++;
 panel.hidden=false;
 panel.innerHTML=`<div class="long-dataset-heading"><div><strong>누적 기억 비교셋 v2.0.0</strong><p>원문 288개 · 기본 질문 288개 + 통제 입력 변형 72개</p></div><label>데이터 프로필<select id="dataset-profile">${option('all','전체 보기 · 실행 항목 360개')}${data.coverage.profiles.map(p=>option(p.id,p.label+' · '+p.count+'문항')).join('')}</select></label></div><p class="long-profile-description">${esc(selected?.description||'개발 원문 192개 + 최종용 원문 96개. 전체 목록을 보되 실제 실행은 프로필 또는 이야기별로 나눠 주세요.')}</p><div class="meta">${badge('PENDING_REVIEW','정답·관계 · 작성자 초안')}${badge('actual','실제 모델 평가 미실행')}<span>36개 기억 묶음 × 원문 8개</span></div><p class="hint">원문 내부 반복으로 길이를 늘리지 않았습니다. 같은 사건의 원문 간 재인용은 중복 검사입니다. 실제 토큰수는 미측정이며 Full은 대화 형식을 포함한 전체 입력 예산으로 검사합니다. 최종용은 개발에 사용하지 않도록 별도 선택합니다.</p>${q?`<div class="long-case-meta"><strong>${esc(q.display_case_id)}</strong><span>${q.split==='final'?'최종용 · 설정 확정 후 사용':'개발용'}</span><span>현재 기억 원문 ${refs.length}개 · ${refs.reduce((n,r)=>n+Array.from(data.sources.records.find(s=>s.id===r.source_id)?.text||'').length,0)}자</span>${q.variant?'<span>통제 입력 변형 · 독립 질문 아님</span>':''}</div>`:''}<details><summary>이전 489개 변수와 연결 · 부분 ${counts.PARTIAL} / 미포함 ${counts.NOT_COVERED} / 별도 기능 검사 ${counts.SEPARATE_FUNCTIONAL_TEST}</summary><p class="hint">연결은 작성자 초안이며 공식 커버리지나 모델 통과를 뜻하지 않습니다. 삭제·권한·캐시·UI·장애는 고정 원문만으로 검증하지 않습니다.</p><div class="ds-variable-scroll">${data.coverage.variables.map(v=>`<p><strong>${esc(v.id)}</strong> · ${esc(({PARTIAL:'부분 연결',NOT_COVERED:'미포함',SEPARATE_FUNCTIONAL_TEST:'별도 기능 검사'})[v.status])} · ${esc(v.description)}${v.case_ids.length?' → '+esc(v.case_ids.join(', ')):''}</p>`).join('')}</div></details>`;
 const select=$('#dataset-profile');select.value=datasetProfile;select.onchange=()=>{datasetProfile=select.value;$('#family').value='';$('#question-search').value='';if(!profileQuestions().some(q=>q.id===questionId))questionId=profileQuestions()[0].id;selectQuestion(questionId).catch(error=>notify(error.message));};
}


// Longitudinal dataset: counts and offline tokens are descriptive, never an inference trigger.
function renderLongitudinalInfo(){
 const m=data.manifest,panel=$('#long-dataset-info'),q=currentQuestion(),c=contextFor(q),rows=data.token_measurements?.questions||[],t=rows.find(r=>r.question_id===q?.id),sources=(c?.expected_state.accessible_sources||[]).map(r=>data.sources.records.find(s=>s.id===r.source_id)),p=data.coverage.profiles.find(p=>p.id===datasetProfile);
 panel.hidden=false;panel.innerHTML=`<div class="long-dataset-heading"><div><strong>${esc(m.title)}</strong>${m.content_revision?`<small>내용 추가 · ${esc(m.content_revision)}</small>`:''}<p>작성 원문 ${m.counts.authored_notes}개 · 상태용 ${m.counts.fixture_sources}개 · 길이 내보내기 ${m.counts.derived_exports}개</p><p>기본 질문 ${m.counts.base_questions}개 + 입력 변형 ${m.counts.controlled_variants}개 = ${m.counts.questions}개 실행 항목</p></div><label>데이터 프로필<select id="dataset-profile">${option('all','전체 보기 · '+m.counts.questions+'개')}${data.coverage.profiles.map(p=>option(p.id,p.label+' · '+p.count+'개')).join('')}</select></label></div><p>${esc(p?.description||'개발·최종을 분리하고 프로필별로 실행합니다. 실제 모델 평가는 사용자가 시작합니다.')}</p>${m.counts.natural_reading_originals?`<p>자연 장문 독해 · 원문 ${m.counts.natural_reading_originals}개 / 질문 ${m.counts.natural_reading_questions}개 · 서술형 회고·회의 대화·이메일·혼합 입력</p>`:''}<p class="hint">원문 600·1800·3000·3999·4000·4001·7999·8000·8001·8500·12000·24000자. 누적 기억은 실제 본문 합계가 단계 기준을 넘는 시점까지 모두 포함합니다. 날짜·제목으로 길이를 채운 것으로 대체하지 않습니다.</p><div class="meta">${badge('PENDING_REVIEW','정답 초안 · 독립 의미 검토 전')}${badge('actual','어휘 토큰 계산만 · 모델 추론 미실행')}<span>${q?.split==='final'?'최종용 · 개발에 사용하지 않기':'개발용'}</span><span>현재 기억 ${sources.length}개 · 본문 ${sources.reduce((n,s)=>n+(s?.text.length||0),0).toLocaleString()}자</span></div>${t?`<p class="hint">기본 프롬프트 기준 · 오프라인 근거 JSON ${t.evidence_tokens.toLocaleString()}토큰 · 입력 본문 ${t.input_content_tokens.toLocaleString()}토큰 · 기존 2048 근거 제한 정책에서 ${t.full_eligible_offline?'예산 이내':'예산 초과'}였던 측정값 · 현재 정책의 가능 여부는 선택 질문 토큰 확인으로 재계산. ${c?.dialogue?'앞 턴 실제 출력이 추가되면 실행 시 다시 측정합니다.':'채팅 템플릿 여유와 실제 서버 사용량은 별도입니다.'}</p>`:''}<details><summary>보완한 조건과 이전 변수 연결</summary>${data.coverage.features.map(f=>`<p>· ${esc(f.note)}</p>`).join('')}<div class="ds-variable-scroll">${data.coverage.variables.map(v=>`<p><strong>${esc(v.id)}</strong> · ${esc(({PARTIAL:'의미 사례 부분 연결',FIXTURE_ONLY:'합성 상태만 검사',NOT_COVERED:'미포함',SEPARATE_FUNCTIONAL_TEST:'별도 제품 검사'})[v.status])} · ${esc(v.description)}${v.question_ids.length?' → '+esc(v.question_ids.slice(0,8).join(', '))+(v.question_ids.length>8?' 외 '+(v.question_ids.length-8)+'개':''):''}</p>`).join('')}</div></details>`;
 const select=$('#dataset-profile');select.value=datasetProfile;select.onchange=()=>{datasetProfile=select.value;$('#family').value='';$('#question-search').value='';if(!profileQuestions().some(q=>q.id===questionId))questionId=profileQuestions()[0].id;selectQuestion(questionId).catch(e=>notify(e.message));};
}
function dsTokenInfoHTML(q){const d=datasetBrowser.ds,t=d?.token_measurements?.questions.find(r=>r.question_id===q.id);if(!t)return '';return `<section class="card"><h2>입력 길이와 토큰</h2><p>근거 JSON ${t.evidence_tokens.toLocaleString()}토큰 · 입력 내용 ${t.input_content_tokens.toLocaleString()}토큰</p><p>${t.full_eligible_offline?'기존 근거 제한 정책에서 예산 이내':'기존 근거 제한 정책에서 예산 초과'} · 현재 정책의 가능 여부는 워크벤치에서 다시 계산합니다.</p><p class="hint">실제 로컬 모델 어휘로 계산했습니다. 모델 추론이나 서버 호출을 하지 않았으며 다른 모델과 실제 생성 대화에서는 다시 측정합니다.</p></section>`;}
function dsDialogueInfoHTML(q){const c=datasetBrowser.contexts.get(q.context_id);if(!c?.dialogue)return '';return `<section class="card"><h2>실제 후속 대화 · ${c.dialogue.turn}턴</h2><p>앞선 턴 ${c.dialogue.depends_on.length}개를 먼저 실행하고 실제 생성 답변을 이어받습니다.</p><p class="hint">단일 질문 실행을 선택해도 필요한 앞 턴이 함께 선택됩니다. 첫 턴 오류를 마지막 정답으로 덮지 않고 전체 대화에서 확인합니다.</p></section>`;}
function renderDialogueVerdict(run){const panel=$('#gold-panel');if(!run?.dialogue_summaries?.length)return;panel.innerHTML+=`<details class="dialogue-summary" open><summary>대화 전체 판정</summary>${run.dialogue_summaries.map(g=>{const human=(run.reviews||[]).filter(r=>g.question_ids.includes(r.question_id)),failed=g.status==='FAIL'||human.some(r=>r.verdict==='FAIL'),passed=g.executed_turns===g.expected_turns&&g.question_ids.every(id=>human.some(r=>r.question_id===id&&r.verdict==='PASS'));return `<p><strong>${esc(g.id)}</strong> · ${g.executed_turns}/${g.expected_turns}턴 · ${failed?'실패 포함':passed?'사람 판정 전체 통과':g.status==='NOT_APPLICABLE'?'예산 초과 포함 · 비교 제외':'전체 의미 검토 대기'}</p>`;}).join('')}<p class="hint">마지막 답변만으로 대화 전체 통과를 판정하지 않습니다.</p></details>`;}

function actionLabel(key){return ({answer:"직접 답변",abstain:"정보 부족 안내",deny:"잘못된 전제 교정",clarify:"명확화 질문",partial_answer:"부분 답변",report_conflict:"충돌 설명"})[key]||esc(key);}

function readingFormatName(value){return ({narrative:'서술형 회고',transcript:'회의 대화',email:'이메일 흐름',mixed:'주제가 섞인 입력'})[value]||value;}
function dsNaturalReadingHTML(q){if(!q.reading_skills)return '';return `<section class="card"><h2>자연 장문 독해 · ${esc(readingFormatName(q.text_format))}</h2><p>${q.reading_skills.map(esc).join(' · ')}</p><p class="hint">메모 내보내기를 합친 글이 아니라 처음부터 문단이 연결되도록 작성한 원문입니다. 근거 연결은 작성자 초안이며 문단 수를 추론 단계 수로 자동 환산하지 않습니다.</p></section>`;}

function renderGeneralizationInfo(){
 const panel=$('#long-dataset-info');panel.hidden=false;
 panel.innerHTML='<div class="long-dataset-heading"><div><strong>일반화 최소 기준점 · v3 기반</strong><p>개발용 30문항 · 확인용 30문항 · 각 목록은 능력 6개 × 조건 4개 + 대화 5턴 + 빈 기억 1개</p></div><label>테스트 목록<select id="dataset-profile">'+data.coverage.profiles.map(p=>option(p.id,p.label)).join('')+option('all','두 목록 전체 · 60문항')+'</select></label></div><p class="long-profile-description">'+esc(data.coverage.profiles.find(p=>p.id===datasetProfile)?.description||'두 목록을 모두 수정에 사용하면 별도 확인용으로 다시 주장하지 마세요.')+'</p><p class="hint">삭제·접근 불가 기억 사용과 근거 없는 단정을 우선 확인합니다. 정답은 작성자 재검토 상태이며 독립 검토는 미완료입니다. 토큰수·성능은 미측정이고 상태 변화는 합성 검사입니다.</p>';
 const select=$('#dataset-profile');select.value=datasetProfile;select.onchange=()=>{datasetProfile=select.value;$('#family').value='';$('#question-search').value='';if(!profileQuestions().some(q=>q.id===questionId))questionId=profileQuestions()[0].id;initializeDatasetProfile();selectQuestion(questionId).catch(e=>notify(e.message));};
}
